static bool g_reallocFailsNext = false;

extern "C" bool __wrap_jsoncanon_tryWrite(const char* body, size_t body_len, JsonBuf_t* json_buf)
{
  g_jsonCanonCallCount++;
  return __real_jsoncanon_tryWrite(body, body_len, json_buf);
}

static int64_t g_clockShiftMs  = 0;
static bool    g_isClockFrozen = false;
static int64_t g_frozenClockMs = 0;

extern "C" int64_t __wrap_monotonic_nowMs(void)
{
  int64_t real_ms = g_isClockFrozen ? g_frozenClockMs : __real_monotonic_nowMs();
  return real_ms + g_clockShiftMs;
}

extern "C" void* __wrap_realloc(void* ptr, size_t size)
{
  if (g_reallocFailsNext)
  {
    g_reallocFailsNext = false;
    return NULL;
  }
  return __real_realloc(ptr, size);
}

static volatile size_t       g_mallocFailSize       = 0;
static volatile unsigned int g_mallocFailSkipCount  = 0;
static volatile unsigned int g_mallocFailExtraCount = 0;

extern "C" void* __wrap_malloc(size_t size)
{
  if (g_mallocFailSize != 0 && size == g_mallocFailSize)
  {
    if (g_mallocFailSkipCount > 0)
    {
      g_mallocFailSkipCount = g_mallocFailSkipCount - 1;
      return __real_malloc(size);
    }
    if (g_mallocFailExtraCount > 0)
      g_mallocFailExtraCount = g_mallocFailExtraCount - 1;
    else
      g_mallocFailSize = 0;
    return NULL;
  }
  return __real_malloc(size);
}

static size_t g_callocFailSize = 0;

extern "C" void* __wrap_calloc(size_t count, size_t size)
{
  if (count == 0 || size == 0)
    return NULL;
  if (g_callocFailSize != 0 && size == g_callocFailSize)
  {
    g_callocFailSize = 0;
    return NULL;
  }
  return __real_calloc(count, size);
}

#define BZERO_RECORD_MAX_COUNT  64
#define BZERO_RECORD_BYTE_COUNT 96
static size_t g_bzeroRecordCount = 0;
static size_t g_bzeroRecordLength[BZERO_RECORD_MAX_COUNT];
static char   g_bzeroRecordBytes[BZERO_RECORD_MAX_COUNT][BZERO_RECORD_BYTE_COUNT];

static void static_recordBzero(const void* address, size_t length)
{
  if (g_bzeroRecordCount >= BZERO_RECORD_MAX_COUNT)
    return;
  size_t copied = length < BZERO_RECORD_BYTE_COUNT ? length : BZERO_RECORD_BYTE_COUNT;
  g_bzeroRecordLength[g_bzeroRecordCount] = length;
  memset(g_bzeroRecordBytes[g_bzeroRecordCount], 0, BZERO_RECORD_BYTE_COUNT);
  memcpy(g_bzeroRecordBytes[g_bzeroRecordCount], address, copied);
  g_bzeroRecordCount++;
}

extern "C" void __wrap_explicit_bzero(void* address, size_t length)
{
  static_recordBzero(address, length);
  __real_explicit_bzero(address, length);
}

extern "C" void __wrap___explicit_bzero_chk(void* address, size_t length, size_t address_size)
{
  static_recordBzero(address, length);
  __real___explicit_bzero_chk(address, length, address_size);
}

static size_t g_digestFailByteCount = 0;

extern "C" int __wrap_EVP_Digest(const void* data, size_t count, unsigned char* md, unsigned int* size, const EVP_MD* type, ENGINE* impl)
{
  if (g_digestFailByteCount != 0 && count == g_digestFailByteCount)
  {
    g_digestFailByteCount = 0;
    return 0;
  }
  return __real_EVP_Digest(data, count, md, size, type, impl);
}

static bool static_isBzeroRecorded(size_t length, const char* prefix, size_t prefix_len)
{
  for (size_t i = 0; i < g_bzeroRecordCount; i++)
    if (g_bzeroRecordLength[i] == length && memcmp(g_bzeroRecordBytes[i], prefix, prefix_len) == 0)
      return true;
  return false;
}

