static void static_sha256Hex(const char* text, char* hash_hex_out)
{
  unsigned char digest[EVP_MAX_MD_SIZE];
  unsigned int  digest_len = 0;
  TEST_ASSERT_EQUAL_INT(1, EVP_Digest(text, strlen(text), digest, &digest_len, EVP_sha256(), NULL));
  TEST_ASSERT_EQUAL_UINT(KEYVAULT_VENDOR_KEY_LINK_HASH_HEX_LEN / 2, digest_len);
  for (unsigned int i = 0; i < digest_len; i++)
    snprintf(hash_hex_out + 2 * i, 3, "%02x", digest[i]);
}

static void static_assertManageLink(const char* link, const char* label)
{
  for (size_t c = 0; c < KEYVAULT_VENDOR_KEY_LINK_LEN; c++)
    TEST_ASSERT_NOT_NULL_MESSAGE(strchr("0123456789abcdef", link[c]), label);
  char link_text[KEYVAULT_VENDOR_KEY_LINK_LEN + 1];
  memcpy(link_text, link, KEYVAULT_VENDOR_KEY_LINK_LEN);
  link_text[KEYVAULT_VENDOR_KEY_LINK_LEN] = '\0';
  char link_hash[KEYVAULT_VENDOR_KEY_LINK_HASH_HEX_LEN + 1];
  static_sha256Hex(link_text, link_hash);
  TEST_ASSERT_EQUAL_STRING_MESSAGE(link_hash, g_stub_vendor_key_link_open_last_link_hash, label);
  TEST_ASSERT_TRUE_MESSAGE(strcmp(link_text, g_stub_vendor_key_link_open_last_link_hash) != 0, label);
  TEST_ASSERT_EQUAL_INT64_MESSAGE(VENDORKEY_TEST_API_KEY_ID, g_stub_vendor_key_link_open_last_api_key_id, label);
}

