void tearDown(void)
{
  g_conn = NULL;
  x402_request_start(NULL);
  for (; g_enteredUpstreamThreadCount > 0; g_enteredUpstreamThreadCount--)
    upstream_leave();
}

static void static_useEveryUpstreamThread(void)
{
  TEST_ASSERT_TRUE_MESSAGE(upstream_tryEnter(), "setUp allows one upstream thread");
  g_enteredUpstreamThreadCount++;
}

typedef struct
{
  int    m_fd;
  char*  mp_buf;
  size_t m_capacity;
  size_t m_received;
} ResponseReader_t;

static void* static_drainResponse(void* arg)
{
  ResponseReader_t* reader = (ResponseReader_t*)arg;
  char discard[4096];
  for (;;)
  {
    size_t kept = reader->m_received < reader->m_capacity ? reader->m_received : reader->m_capacity;
    size_t room = reader->m_capacity - kept;
    char*  dst  = room > 0 ? reader->mp_buf + kept : discard;
    size_t want = room > 0 ? room : sizeof(discard);
    ssize_t n = read(reader->m_fd, dst, want);
    if (n <= 0)
      break;
    reader->m_received += (size_t)n;
  }
  return NULL;
}

typedef void (*ResponseWriter_t)(int client_fd, const void* context);

static bool static_collectResponse(ResponseWriter_t write_response, const void* context, char* buf, size_t len)
{
  int fds[2];
  if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) < 0)
  {
    perror("socketpair");
    buf[0] = '\0';
    return false;
  }
  ResponseReader_t reader = { fds[0], buf, len - 1, 0 };
  pthread_t reader_thread;
  if (pthread_create(&reader_thread, NULL, static_drainResponse, &reader) != 0)
  {
    perror("pthread_create");
    close(fds[0]);
    close(fds[1]);
    buf[0] = '\0';
    return false;
  }
  write_response(fds[1], context);
  bool left_open = fcntl(fds[1], F_GETFD) != -1;
  if (left_open)
    close(fds[1]);
  pthread_join(reader_thread, NULL);
  close(fds[0]);
  size_t kept = reader.m_received < reader.m_capacity ? reader.m_received : reader.m_capacity;
  buf[kept] = '\0';
  TEST_ASSERT_TRUE_MESSAGE(reader.m_received <= reader.m_capacity, "response did not fit the caller's buffer");
  return left_open;
}

typedef struct
{
  const char* mp_request;
  const char* mp_secret;
} RequestHandleCall_t;

static void static_writeRequestHandle(int client_fd, const void* context)
{
  const RequestHandleCall_t* call = (const RequestHandleCall_t*)context;
  ReceiveResult_t request;
  TEST_ASSERT_TRUE_MESSAGE(requestText_parse(call->mp_request, &request), call->mp_request);
  RequestHead_t head;
  request_readHead(&request, &head);
  request_handle(&request, &head, client_fd, TEST_IP, call->mp_secret, g_conn);
}

typedef struct
{
  const char* mp_head;
  const char* mp_body;
  size_t      m_bodyLen;
} BinaryRequestCall_t;

static void static_writeBinaryRequestHandle(int client_fd, const void* context)
{
  const BinaryRequestCall_t* call = (const BinaryRequestCall_t*)context;
  ReceiveResult_t request;
  TEST_ASSERT_TRUE_MESSAGE(requestText_parse(call->mp_head, &request), call->mp_head);
  request.mp_body   = call->mp_body;
  request.m_bodyLen = call->m_bodyLen;
  RequestHead_t head;
  request_readHead(&request, &head);
  request_handle(&request, &head, client_fd, TEST_IP, NULL, g_conn);
}

static void static_callRequestHandleWithSecret(const char* req, const char* secret, char* buf, size_t len)
{
  RequestHandleCall_t call = { req, secret };
  bool left_open = static_collectResponse(static_writeRequestHandle, &call, buf, len);
  TEST_ASSERT_FALSE_MESSAGE(left_open, "request_handle left the client socket open");
}

static void static_callRequestHandle(const char* req, char* buf, size_t len)
{
  static_callRequestHandleWithSecret(req, NULL, buf, len);
}


void test_valid_key_found_in_db_reaches_route(void)
{
  g_stub_api_key_state = DB_API_KEY_ACTIVE;

  const char* req =
    "GET /health HTTP/1.1\r\n"
    "X-API-Key: " VALID_KEY "\r\n\r\n";
  char buf[RESP_BUF];
  static_callRequestHandle(req, buf, sizeof(buf));
  TEST_ASSERT_NOT_NULL(strstr(buf, "HTTP/1.1 200"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("status":"ok")"));
}

