#define OVERLONG_LEN   129
#define MAXFIT_LEN     128

static void static_buildLongRequest(char* out_buf, size_t out_buf_size, const char* before, size_t value_len, char fill, const char* after)
{
  size_t before_len = strlen(before);
  size_t after_len  = strlen(after);
  TEST_ASSERT_TRUE(before_len + value_len + after_len + 1 <= out_buf_size);
  memcpy(out_buf, before, before_len);
  memset(out_buf + before_len, fill, value_len);
  memcpy(out_buf + before_len + value_len, after, after_len);
  out_buf[before_len + value_len + after_len] = '\0';
}

