void test_PRODUCTEXPOSURE_version_reaches_the_query_and_a_bad_one_is_refused(void)
{
  g_stub_PRODUCTEXPOSURE_status = DB_OK;
  g_stub_PRODUCTEXPOSURE_last_params.m_isRejectedIncluded = true;
  char buf[RESP_BUF];
  static_callRequestHandle("GET /product_exposure?vendor=nodejs&product=node.js&version=v22.21.1 HTTP/1.1\r\nHost: localhost\r\n\r\n",
                           buf, sizeof(buf));
  TEST_ASSERT_NOT_NULL(strstr(buf, "HTTP/1.1 200"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("eol":null})"));
  TEST_ASSERT_EQUAL_STRING("v22.21.1", g_stub_PRODUCTEXPOSURE_last_params.ma_version);
  TEST_ASSERT_FALSE(g_stub_PRODUCTEXPOSURE_last_params.m_isRejectedIncluded);

  snprintf(g_stub_PRODUCTEXPOSURE_last_params.ma_version, sizeof(g_stub_PRODUCTEXPOSURE_last_params.ma_version), "unset");
  char req[512];
  static_buildLongRequest(req, sizeof(req), "GET /product_exposure?vendor=nodejs&product=node.js&version=", PRODUCTEXPOSURE_VERSION_MAX_LEN + 1, 'a',
                          " HTTP/1.1\r\nHost: localhost\r\n\r\n");
  static_callRequestHandle(req, buf, sizeof(buf));
  TEST_ASSERT_NOT_NULL(strstr(buf, "HTTP/1.1 400"));
  TEST_ASSERT_NOT_NULL(strstr(buf, "version is too long"));

  static_callRequestHandle("GET /product_exposure?vendor=nodejs&product=node.js&version=22%091 HTTP/1.1\r\nHost: localhost\r\n\r\n",
                           buf, sizeof(buf));
  TEST_ASSERT_NOT_NULL(strstr(buf, "HTTP/1.1 400"));
  TEST_ASSERT_EQUAL_STRING("unset", g_stub_PRODUCTEXPOSURE_last_params.ma_version);
}

static int static_countResponses(const char* buf)
{
  int response_count = 0;
  for (const char* cursor = buf; (cursor = strstr(cursor, "HTTP/1.1 ")) != NULL; cursor += 9)
    response_count++;
  return response_count;
}

static const char* static_responseBody(const char* buf)
{
  const char* head_end = strstr(buf, "\r\n\r\n");
  TEST_ASSERT_NOT_NULL_MESSAGE(head_end, "the response has no blank line after its head");
  return head_end + strlen("\r\n\r\n");
}

