void test_web_file_answer_has_its_headers_and_no_rate_limit_headers(void)
{
  const PagesFile_t* file = pages_findServedFile("/static/style.css");
  TEST_ASSERT_NOT_NULL(file);
  static char buf[65536];
  static_callRequestHandle("GET /static/style.css?v=29 HTTP/1.1\r\n\r\n", buf, sizeof(buf));
  TEST_ASSERT_NOT_NULL(strstr(buf, "HTTP/1.1 200 OK\r\n"));
  TEST_ASSERT_NOT_NULL(strstr(buf, "\r\nContent-Type: text/css; charset=utf-8\r\n"));
  TEST_ASSERT_NOT_NULL(strstr(buf, "\r\nCache-Control: public, max-age=3600\r\n"));
  TEST_ASSERT_NULL(strstr(buf, "X-RateLimit-"));
  TEST_ASSERT_EQUAL_UINT(CREDIT_COST_SENTINEL, g_stub_last_credit_cost);

  char content_length[64];
  snprintf(content_length, sizeof(content_length), "\r\nContent-Length: %zu\r\n", file->m_bodyByteCount);
  TEST_ASSERT_NOT_NULL(strstr(buf, content_length));
  const char* body = strstr(buf, "\r\n\r\n");
  TEST_ASSERT_NOT_NULL(body);
  body += 4;
  TEST_ASSERT_EQUAL_UINT(file->m_bodyByteCount, strlen(body));
  TEST_ASSERT_EQUAL_INT(0, memcmp(file->mp_body, body, file->m_bodyByteCount));
}

