static void static_CVELOOKUPWithGhsa(const char* ghsa_value, char* buf, size_t len)
{
  g_stub_CVELOOKUP_status = DB_OK;
  char req[256];
  int n = snprintf(req, sizeof(req),
    "GET /cve_lookup/CVE-2021-44228?include_ghsa=%s HTTP/1.1\r\nHost: localhost\r\n\r\n",
    ghsa_value);
  (void)n;
  static_callRequestHandle(req, buf, len);
}

