void test_CVELOOKUP_ghsa_gate_answers_and_clears(void)
{
  const Endpoint_t* endpoint = endpoint_findByHttpPath("/cve_lookup/", NULL);
  TEST_ASSERT_NOT_NULL(endpoint);
  char too_long[64];
  static_buildLongRequest(too_long, sizeof(too_long), "include_ghsa=", 41, 'x', "");
  const struct { const char* mp_query; EndpointGateStatus_t m_status; bool m_isGhsaIncluded; } cases[] = {
    { "",                     ENDPOINT_GATE_OK,                        false },
    { "?other=1",             ENDPOINT_GATE_REJECT_UNKNOWN_PARAM_NAME, false },
    { "?include=ghsa",        ENDPOINT_GATE_REJECT_UNKNOWN_PARAM_NAME, false },
    { "include_ghsa=false",           ENDPOINT_GATE_OK,                        false },
    { "?include_ghsa=",               ENDPOINT_GATE_REJECT_VALUE,              false },
    { "?include_ghsa=1",              ENDPOINT_GATE_REJECT_VALUE,              false },
    { too_long,               ENDPOINT_GATE_REJECT_TOOLONG,            false },
    { "?include_ghsa=true",           ENDPOINT_GATE_OK,                        true  },
  };
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    CVELOOKUPParams_t params;
    memset(&params, 0, sizeof(params));
    params.m_isGhsaIncluded = !cases[i].m_isGhsaIncluded;
    TEST_ASSERT_EQUAL_INT_MESSAGE(cases[i].m_status, endpoint_restQueryGate(endpoint, cases[i].mp_query, &params, sizeof(params)).m_status, cases[i].mp_query);
    TEST_ASSERT_TRUE_MESSAGE(params.m_isGhsaIncluded == cases[i].m_isGhsaIncluded, cases[i].mp_query);
  }
}

