void test_bulk_lookups_equal_the_charged_credits(void)
{
  g_stub_api_key_state    = DB_API_KEY_ACTIVE;
  g_stub_CVELOOKUP_status = DB_OK;

  for (unsigned int remaining = 1; remaining <= 5; remaining++)
  {
    char message[64];
    snprintf(message, sizeof(message), "%u credits left", remaining);
    char buf[RESP_BUF * 4];

    g_stub_credit_budget_remaining = remaining;
    g_stub_CVELOOKUPBULK_id_count = 0;
    static_postBulk("/cve_lookup_bulk", buf, sizeof(buf));
    TEST_ASSERT_EQUAL_INT_MESSAGE((int)remaining, g_stub_CVELOOKUPBULK_id_count, message);

    g_stub_CVELOOKUPBULK_id_count = 0;
    static_postBulkTool("cve_lookup_bulk", buf, sizeof(buf));
    TEST_ASSERT_EQUAL_INT_MESSAGE((int)remaining, g_stub_CVELOOKUPBULK_id_count, message);
  }
}

