static void static_errorMessageOf(const char* buf, char* out, size_t out_size);
static void static_assertEveryMention(const char* text, const char* anchor, const char* message, char closing_mark);

static unsigned int static_retryAfterOf(const char* buf)
{
  const char* header = strstr(buf, "\r\nRetry-After: ");
  TEST_ASSERT_NOT_NULL_MESSAGE(header, "the response has no Retry-After header");
  return (unsigned int)strtoul(header + strlen("\r\nRetry-After: "), NULL, 10);
}

