void test_refused_upstream_request_does_not_enter(void)
{
  g_stub_api_key_state = DB_API_KEY_ACTIVE;
  static_useEveryUpstreamThread();

  static const struct { const char* mp_request; const char* mp_status; } rest[] = {
    { "POST /password_check/5BAA61E4C9B93F3F0682250B6CF8331B7EE68FD8 HTTP/1.1\r\n\r\n",  "HTTP/1.1 405" },
    { "GET /password_check/5BAA61E4C9B93F3F0682250B6CF8331B7EE68FD8?x=1 HTTP/1.1\r\n\r\n", "HTTP/1.1 400" },
    { "GET /password_check/5BAA6 HTTP/1.1\r\n\r\n",                       "HTTP/1.1 400" },
    { "GET /password_check/ HTTP/1.1\r\n\r\n",                            "HTTP/1.1 400" },
    { "GET /dns_lookup/printer.local HTTP/1.1\r\n\r\n",                  "HTTP/1.1 400" },
    { "GET /dns_lookup/ HTTP/1.1\r\n\r\n",                                "HTTP/1.1 400" },
    { "GET /dns_takeover_check/router.home.arpa HTTP/1.1\r\n\r\n",           "HTTP/1.1 400" },
    { "GET /email_auth_check/example.com?dkim_selector=a_b HTTP/1.1\r\n\r\n", "HTTP/1.1 400" },
    { "GET /ip_lookup/10.0.0.1 HTTP/1.1\r\n\r\n",                     "HTTP/1.1 400" },
    { "GET /ssl_check/printer.local HTTP/1.1\r\n\r\n",                    "HTTP/1.1 400" },
    { "GET /whois_lookup/printer.local HTTP/1.1\r\n\r\n",                 "HTTP/1.1 400" },
    { "GET /wayback_lookup/printer.local HTTP/1.1\r\n\r\n",               "HTTP/1.1 400" },
    { "GET /cert_search/printer.local HTTP/1.1\r\n\r\n",                  "HTTP/1.1 400" },
    { "GET /subdomain_enum/printer.local HTTP/1.1\r\n\r\n",               "HTTP/1.1 400" },
    { "GET /headers_check/printer.local HTTP/1.1\r\n\r\n",                "HTTP/1.1 400" },
    { "GET /headers_check/example.com?include_full_header_values=yes HTTP/1.1\r\n\r\n", "HTTP/1.1 400" },
  };
  char buf[RESP_BUF];
  for (size_t i = 0; i < sizeof(rest) / sizeof(rest[0]); i++)
  {
    static_callRequestHandle(rest[i].mp_request, buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, rest[i].mp_status), rest[i].mp_request);
  }

  static const char* const mcp_arguments[][2] = {
    { "password_check", R"({"sha1_hash":"5BAA6"})" },
    { "dns_lookup",     R"({"domain":"printer.local"})" },
    { "dns_takeover_check", R"({"domain":"router.home.arpa"})" },
    { "email_auth_check",   R"({"domain":"example.com","dkim_selector":"a_b"})" },
    { "ip_lookup",          R"({"ip_address":"10.0.0.1"})" },
    { "ssl_check",          R"({"domain":"printer.local"})" },
    { "whois_lookup",       R"({"domain":"printer.local"})" },
    { "wayback_lookup",     R"({"domain":"printer.local"})" },
    { "cert_search",        R"({"domain":"printer.local"})" },
    { "subdomain_enum",     R"({"domain":"printer.local"})" },
    { "headers_check",      R"({"domain":"printer.local"})" },
    { "headers_check",      R"({"domain":"example.com","include_full_header_values":"yes"})" },
  };
  char req[512];
  for (size_t i = 0; i < sizeof(mcp_arguments) / sizeof(mcp_arguments[0]); i++)
  {
    int written = snprintf(req, sizeof(req), "POST /mcp HTTP/1.1\r\nContent-Type: application/json\r\n\r\n"
                           R"({"jsonrpc":"2.0","id":33,"method":"tools/call","params":{"name":"%s","arguments":%s}})",
                           mcp_arguments[i][0], mcp_arguments[i][1]);
    TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(req));
    static_callRequestHandle(req, buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 200"), mcp_arguments[i][1]);
  }
  TEST_ASSERT_FALSE(upstream_tryEnter());
  TEST_ASSERT_EQUAL_INT(0, g_stub_PASSWORDCHECK_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_DNSLOOKUP_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_DNSTAKEOVERCHECK_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_EMAILAUTHCHECK_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_IPLOOKUP_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_PTR_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_TLSPROBE_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_RDAP_find_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_RDAP_lookup_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_WAYBACK_lookup_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CERTSPOTTER_lookup_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CERTSPOTTER_subtree_lookup_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_SUBDOMAIN_lookup_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_HEADER_FETCH_call_count);
}

