void test_package_check_bulk_empty_or_one_credit_budget_runs_no_weigh(void)
{
  for (size_t t = 0; t < sizeof(g_weighTransports) / sizeof(g_weighTransports[0]); t++)
  {
    setUp();
    g_stub_api_key_state           = DB_API_KEY_ACTIVE;
    g_stub_PACKAGECHECKBULK_status = DB_OK;
    g_stub_credit_budget_remaining = 0;
    g_stub_credit_budget_reset     = time(NULL) + 60;
    char buf[RESP_BUF];
    static_sendPackageCheckBulk(g_weighTransports[t], true, WEIGH_ITEMS, buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 429 Too Many Requests\r\n"), buf);
    char limit_line[64];
    snprintf(limit_line, sizeof(limit_line), "\r\nX-RateLimit-Limit: %u\r\n", (unsigned int)RL_KEY_CREDIT_LIMIT);
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, limit_line), buf);
    TEST_ASSERT_NULL_MESSAGE(strstr(buf, "\r\nRetry-After: 0\r\n"), buf);
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "\r\nRetry-After: "), buf);
    TEST_ASSERT_EQUAL_INT(1, g_stub_credit_budget_remaining_call_count);
    TEST_ASSERT_EQUAL_INT(0, g_stub_PACKAGECHECKBULKWeigh_call_count);
    TEST_ASSERT_EQUAL_INT(0, g_stub_credit_budget_check_call_count);
    TEST_ASSERT_EQUAL_INT(0, g_stub_PACKAGECHECKBULK_call_count);

    setUp();
    g_stub_api_key_state           = DB_API_KEY_ACTIVE;
    g_stub_PACKAGECHECKBULK_status = DB_OK;
    g_stub_credit_budget_remaining = 1;
    static_sendPackageCheckBulk(g_weighTransports[t], true, WEIGH_ITEMS, buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 200 OK\r\n"), buf);
    TEST_ASSERT_EQUAL_INT(0, g_stub_PACKAGECHECKBULKWeigh_call_count);
    TEST_ASSERT_EQUAL_UINT(1, g_stub_last_credit_cost);
    TEST_ASSERT_EQUAL_INT(1, g_stub_PACKAGECHECKBULK_last_item_count);
    TEST_ASSERT_EQUAL_STRING("a", g_stub_PACKAGECHECKBULK_last_items[0].ma_packageName);
  }
}

