void test_path_id_refusals_answer_before_the_db(void)
{
  g_stub_CVELOOKUP_status    = DB_OK;
  g_stub_KEVLOOKUP_status    = DB_OK;
  g_stub_CWELOOKUP_status    = DB_OK;
  g_stub_CVERISKSCORE_status = DB_OK;

  static const struct { const char* mp_request; const char* mp_status; const char* mp_body; } cases[] = {
    { "GET /cve_lookup/not-a-cve?include_ghsa=x HTTP/1.1\r\nHost: localhost\r\n\r\n",    "HTTP/1.1 400 Bad Request\r\n", R"({"error":{"code":"invalid_cve_id","message":"CVE ID must be CVE-YYYY-NNNN[N...]"}})" },
    { "GET /cve_lookup/?include_ghsa=x HTTP/1.1\r\nHost: localhost\r\n\r\n",             "HTTP/1.1 400 Bad Request\r\n", R"({"error":{"code":"bad_request","message":"missing CVE ID"}})" },
    { "GET /kev_lookup/not-a-cve HTTP/1.1\r\nHost: localhost\r\n\r\n",           "HTTP/1.1 400 Bad Request\r\n", R"({"error":{"code":"invalid_cve_id","message":"CVE ID must be CVE-YYYY-NNNN[N...]"}})" },
    { "GET /kev_lookup/ HTTP/1.1\r\nHost: localhost\r\n\r\n",                    "HTTP/1.1 400 Bad Request\r\n", R"({"error":{"code":"bad_request","message":"missing CVE ID"}})" },
    { "GET /cve_risk_score/not-a-cve HTTP/1.1\r\nHost: localhost\r\n\r\n",       "HTTP/1.1 400 Bad Request\r\n", R"({"error":{"code":"invalid_cve_id","message":"CVE ID must be CVE-YYYY-NNNN[N...]"}})" },
    { "GET /cve_risk_score/ HTTP/1.1\r\nHost: localhost\r\n\r\n",                "HTTP/1.1 400 Bad Request\r\n", R"({"error":{"code":"bad_request","message":"missing CVE ID"}})" },
    { "GET /cwe_lookup/not-a-cwe HTTP/1.1\r\nHost: localhost\r\n\r\n",           "HTTP/1.1 400 Bad Request\r\n", R"({"error":{"code":"invalid_cwe_id","message":"CWE ID must be CWE-N"}})" },
    { "GET /cwe_lookup/ HTTP/1.1\r\nHost: localhost\r\n\r\n",                    "HTTP/1.1 400 Bad Request\r\n", R"({"error":{"code":"bad_request","message":"missing CWE ID"}})" },
  };

  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    char buf[RESP_BUF];
    static_callRequestHandle(cases[i].mp_request, buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, cases[i].mp_status), cases[i].mp_request);
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, cases[i].mp_body), cases[i].mp_request);
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), cases[i].mp_request);
  }
  TEST_ASSERT_EQUAL_INT(0, g_stub_CVELOOKUP_call_count);
}

