void test_real_ip_from_a_remote_peer_is_ignored(void)
{
  const char* req =
    "GET /cve_search HTTP/1.1\r\nHost: localhost\r\nX-Real-IP: 8.8.8.8\r\n\r\n";

  int fds[2];
  TEST_ASSERT_TRUE(socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == 0);
  char buf[RESP_BUF];
  g_stub_last_ip_hash[0] = '\0';
  ReceiveResult_t request;
  TEST_ASSERT_TRUE(requestText_parse(req, &request));
  RequestHead_t head;
  request_readHead(&request, &head);
  request_handle(&request, &head, fds[1], "203.0.113.7", NULL, g_conn);
  ssize_t n = read(fds[0], buf, sizeof(buf) - 1);
  buf[n > 0 ? n : 0] = '\0';
  close(fds[0]);

  char remote_peer[SHA256_HEX_LEN + 1];
  snprintf(remote_peer, sizeof(remote_peer), "%s", g_stub_last_ip_hash);

  char claimed[SHA256_HEX_LEN + 1];
  static_bucketForRealIp("8.8.8.8", claimed, sizeof(claimed));

  TEST_ASSERT_TRUE(remote_peer[0] != '\0');
  TEST_ASSERT_FALSE(strcmp(remote_peer, claimed) == 0);
}

