static void static_privacyVendorKeysMember(PGconn* conn, RequestTier_t tier, char* member_out, size_t member_size)
{
  RequestCreditBudget_t credit_budget;
  memset(&credit_budget, 0, sizeof(credit_budget));
  credit_budget.m_tier = tier;
  snprintf(credit_budget.ma_budgetHash, sizeof(credit_budget.ma_budgetHash), "%s", "b0b0b0");
  EndpointAnyParams_t params;
  memset(&params, 0, sizeof(params));
  params.m_privacyMyData.mp_creditBudget = &credit_budget;
  JsonBuf_t* json_buf = jsonbuf_create(256, JSONBUF_DEFAULT_CEILING);
  TEST_ASSERT_NOT_NULL(json_buf);
  const char* message = NULL;
  TEST_ASSERT_EQUAL_INT(ENDPOINT_RUN_OK, endpoint_PRIVACYMYDATARun(conn, &params, json_buf, &message));
  char* body = jsonbuf_finish(json_buf);
  jsonbuf_destroy(json_buf);
  TEST_ASSERT_NOT_NULL(body);
  const char* start = strstr(body, R"("vendor_keys":)");
  const char* end   = strstr(body, R"(,"policy":)");
  TEST_ASSERT_NOT_NULL_MESSAGE(start, body);
  TEST_ASSERT_NOT_NULL_MESSAGE(end, body);
  TEST_ASSERT_TRUE(start < end && (size_t)(end - start) < member_size);
  memcpy(member_out, start, (size_t)(end - start));
  member_out[end - start] = '\0';
  free(body);
}

#define PRIVACY_VENDOR_KEYS_NULL_SHAPE R"("vendor_keys":{"shodan":{"configured":null},"abuseipdb":{"configured":null},"manage_url":null})"

void test_privacy_my_data_pro_shows_the_vendor_keys_and_a_manage_url(void)
{
  const struct { const char* mp_shodanSealed; const char* mp_abuseIpDbSealed; const char* mp_flags; } cases[] = {
    { "01ab", "03ef", R"({"shodan":{"configured":true},"abuseipdb":{"configured":true},)" },
    { "01ab", "",     R"({"shodan":{"configured":true},"abuseipdb":{"configured":false},)" },
    { "",     "03ef", R"({"shodan":{"configured":false},"abuseipdb":{"configured":true},)" },
    { "",     "",     R"({"shodan":{"configured":false},"abuseipdb":{"configured":false},)" },
  };
  char links[4][KEYVAULT_VENDOR_KEY_LINK_LEN + 1];
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    snprintf(g_stub_vendor_keys.ma_shodanSealedHex, sizeof(g_stub_vendor_keys.ma_shodanSealedHex), "%s", cases[i].mp_shodanSealed);
    snprintf(g_stub_vendor_keys.ma_abuseIpDbSealedHex, sizeof(g_stub_vendor_keys.ma_abuseIpDbSealedHex), "%s", cases[i].mp_abuseIpDbSealed);
    g_stub_vendor_keys_last_key_hash[0] = '\0';
    char member[1024];
    static_privacyVendorKeysMember(FAKE_CONN, REQUEST_TIER_PRO, member, sizeof(member));
    TEST_ASSERT_EQUAL_STRING("b0b0b0", g_stub_vendor_keys_last_key_hash);
    char head[256];
    snprintf(head, sizeof(head), R"("vendor_keys":%s"manage_url":"https://api.contrastcyber.com/vendor-keys#l=)", cases[i].mp_flags);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, strncmp(head, member, strlen(head)), member);
    const char* link = member + strlen(head);
    TEST_ASSERT_EQUAL_STRING_MESSAGE("\"}", link + KEYVAULT_VENDOR_KEY_LINK_LEN, member);
    TEST_ASSERT_EQUAL_INT(64, KEYVAULT_VENDOR_KEY_LINK_LEN);
    static_assertManageLink(link, member);
    TEST_ASSERT_EQUAL_INT_MESSAGE((int)i + 1, g_stub_vendor_key_link_open_call_count, member);
    memcpy(links[i], link, KEYVAULT_VENDOR_KEY_LINK_LEN);
    links[i][KEYVAULT_VENDOR_KEY_LINK_LEN] = '\0';
    for (size_t j = 0; j < i; j++)
      TEST_ASSERT_TRUE_MESSAGE(strcmp(links[i], links[j]) != 0, member);
  }
}

