static int static_countOccurrences(const char* haystack, const char* needle)
{
  int    count = 0;
  size_t step  = strlen(needle);
  for (const char* cursor = haystack; (cursor = strstr(cursor, needle)) != NULL; cursor += step)
    count++;
  return count;
}

static void static_assertBodyEndsWith(const char* body, const char* tail)
{
  size_t body_len = strlen(body);
  size_t tail_len = strlen(tail);
  TEST_ASSERT_GREATER_OR_EQUAL_size_t_MESSAGE(2, tail_len,
    "a one-byte tail pins almost nothing: pass the whole terminator");
  TEST_ASSERT_GREATER_OR_EQUAL_size_t(tail_len, body_len);
  TEST_ASSERT_EQUAL_STRING(tail, body + body_len - tail_len);
}

