#define FAT_AFFECTED_PRODUCTS_LEN (80u * 1024u)
#define FAT_BULK_BUF              (16u * 1024u * 1024u)

static void static_CVELOOKUPBULKFillMaxIdsBody(char* body, size_t body_size)
{
  size_t pos = (size_t)snprintf(body, body_size, R"({"cve_ids":[)");
  for (int i = 0; i < CVELOOKUPBULK_MAX_IDS; i++)
    pos += (size_t)snprintf(body + pos, body_size - pos, R"(%s"CVE-2021-%05d")", i ? "," : "", 10000 + i);
  snprintf(body + pos, body_size - pos, "]}");
}

void test_CVELOOKUPBULK_body_just_under_ceiling_ships_whole(void)
{
  g_stub_api_key_state    = DB_API_KEY_ACTIVE;
  g_stub_CVELOOKUP_status = DB_OK;
  g_stub_CVELOOKUP_affected_products_len = FAT_AFFECTED_PRODUCTS_LEN;
  TEST_ASSERT_GREATER_THAN_size_t(JSONBUF_DEFAULT_CEILING / 4 * 3, (size_t)CVELOOKUPBULK_MAX_IDS * FAT_AFFECTED_PRODUCTS_LEN);
  char ids_body[1024];
  static_CVELOOKUPBULKFillMaxIdsBody(ids_body, sizeof(ids_body));
  char* buf = (char*)malloc(FAT_BULK_BUF);
  TEST_ASSERT_NOT_NULL(buf);
  static_CVELOOKUPBULKPostBody(ids_body, buf, FAT_BULK_BUF);
  TEST_ASSERT_EQUAL_INT(1, static_countResponses(buf));
  TEST_ASSERT_NOT_NULL(strstr(buf, "HTTP/1.1 200"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("successful":50)"));
  const char* body = strstr(buf, "\r\n\r\n");
  TEST_ASSERT_NOT_NULL(body);
  body += 4;
  size_t body_len = strlen(body);
  TEST_ASSERT_GREATER_THAN_size_t(JSONBUF_DEFAULT_CEILING / 4 * 3, body_len);
  static_assertBodyEndsWith(body, "]}");
  const char* cursor = body;
  for (int i = 0; i < CVELOOKUPBULK_MAX_IDS; i++)
  {
    char needle[64];
    snprintf(needle, sizeof(needle), R"(%s{"cve_id":"CVE-2021-%05d")", i ? "}\n," : R"("results":[)", 10000 + i);
    cursor = strstr(cursor, needle);
    TEST_ASSERT_NOT_NULL_MESSAGE(cursor, needle);
    cursor += strlen(needle);
  }
  free(buf);
}

