static void static_assertBufferThatCannotBeCreatedAnswers500Once(const char* req)
{
  char buf[RESP_BUF];
  static_callRequestHandle(req, buf, sizeof(buf));
  TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), "first run: one response");
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 200"), "first run: 200");

  g_mallocFailSize = JSONBUF_INITIAL_CAP;
  static_callRequestHandle(req, buf, sizeof(buf));
  TEST_ASSERT_EQUAL_size_t_MESSAGE(0, g_mallocFailSize, "second run: no body malloc was reached");
  TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), "second run: one response");
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 500"), "second run: 500");
}

