static void static_assertErrorBodyThatCannotBeCreatedAnswers500Once(const char* req, const char* first_status)
{
  char buf[RESP_BUF];
  static_callRequestHandle(req, buf, sizeof(buf));
  TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), "first run: one response");
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, first_status), "first run: its own status");

  g_mallocFailSize = HANDLER_ERROR_JSONBUF_INITIAL_CAP;
  static_callRequestHandle(req, buf, sizeof(buf));
  TEST_ASSERT_EQUAL_size_t_MESSAGE(0, g_mallocFailSize, "second run: no error body malloc was reached");
  TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), "second run: one response");
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 500"), "second run: 500");
}

