void test_mcp_refusal_that_cannot_be_created_answers_500_once(void)
{
  struct { const char* first_status; const char* key_header; RateLimitStatus_t limiter; } cases[] = {
    { "HTTP/1.1 401", "X-API-Key: contrastapi_0000\r\n", RATELIMIT_ALLOW },
    { "HTTP/1.1 429", "",                                RATELIMIT_DENY  },
  };
  char req[512];
  char buf[RESP_BUF];
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    g_stub_credit_budget_status = cases[i].limiter;
    snprintf(req, sizeof(req), "POST /mcp HTTP/1.1\r\n%sContent-Type: application/json\r\n\r\n%s",
             cases[i].key_header, R"({"jsonrpc":"2.0","id":16,"method":"tools/list"})");

    static_callRequestHandle(req, buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, cases[i].first_status), cases[i].first_status);

    g_mallocFailSize = HANDLER_ERROR_JSONBUF_INITIAL_CAP;
    static_callRequestHandle(req, buf, sizeof(buf));
    TEST_ASSERT_EQUAL_size_t_MESSAGE(0, g_mallocFailSize, cases[i].first_status);
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), cases[i].first_status);
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 500"), cases[i].first_status);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(R"({"jsonrpc":"2.0","id":null,"error":{"code":-32603,"message":"internal server error"}})",
                                     static_responseBody(buf), cases[i].first_status);
  }
}

