void test_malloc_wrapper_fails_only_the_armed_size(void)
{
  g_mallocFailSize = JSONBUF_INITIAL_CAP;

  void* volatile other = malloc(JSONBUF_INITIAL_CAP - 1);
  void* volatile armed = malloc(JSONBUF_INITIAL_CAP);

  TEST_ASSERT_NOT_NULL_MESSAGE(other, "a malloc of another size must not fail");
  TEST_ASSERT_NULL_MESSAGE(armed, "the malloc of the armed size must fail");
  TEST_ASSERT_EQUAL_size_t(0, g_mallocFailSize);
  free(other);
}

#define DOCS_API_PATH           "docs/API_Documentation.md"
#define DOCS_MCP_PATH           "docs/MCP_Documentation.md"
#define DOCS_ROW_MAX            512
#define DOCS_ROUTE_MAX          64
#define DOCS_TOOL_MAX           64
#define DOCS_PARAM_MAX          64
#define DOCS_ARROW              "\xE2\x86\x92"
#define DOCS_TIMES              "\xC3\x97"
#define DOCS_BULK_BODY          R"({"cve_ids":["CVE-2021-44228","CVE-2022-12345","CVE-2023-99999"]})"
#define DOCS_HASH_BULK_BODY     R"({"hashes":["5f4dcc3b5aa765d61d8327deb882cf99","5baa61e4c9b93f3f0682250b6cf8331b7ee68fd8",")" DB_HIT_SHA256_OF_PASSWORD R"("]})"
#define DOCS_PACKAGE_BULK_BODY  R"({"items":[{"ecosystem":"npm","name":"lodash","version":"4.17.20"},{"ecosystem":"PyPI","name":"django","version":"3.2.0"},{"ecosystem":"Go","name":"golang.org/x/net","version":"v0.1.0"}]})"

static const char* static_docsBulkBodyFor(const Endpoint_t* endpoint)
{
  EndpointParamType_t type = endpoint->m_paramCount > 0 ? endpoint->mp_params[0].mp_spec->m_type : ENDPOINT_PARAM_TYPE_STRING;
  if (endpoint->m_costRule == ENDPOINT_COST_BULK_IDS && type == ENDPOINT_PARAM_TYPE_FILE_HASH_ARRAY)
    return DOCS_HASH_BULK_BODY;
  if (endpoint->m_costRule == ENDPOINT_COST_BULK_IDS && type == ENDPOINT_PARAM_TYPE_PACKAGE_ARRAY)
    return DOCS_PACKAGE_BULK_BODY;
  return DOCS_BULK_BODY;
}
#define DOCS_BULK_ID_COUNT      3u
#define DOCS_NOTIFICATION_BODY  R"({"jsonrpc":"2.0","method":"notifications/initialized"})"

static char* static_readDocsFile(const char* path)
{
  FILE* file = fopen(path, "rb");
  TEST_ASSERT_NOT_NULL_MESSAGE(file, path);
  TEST_ASSERT_EQUAL_INT_MESSAGE(0, fseek(file, 0, SEEK_END), path);
  long size = ftell(file);
  TEST_ASSERT_TRUE_MESSAGE(size > 0, path);
  rewind(file);

  char* text = (char*)malloc((size_t)size + 1);
  TEST_ASSERT_NOT_NULL(text);
  size_t read_len = fread(text, 1, (size_t)size, file);
  fclose(file);
  TEST_ASSERT_EQUAL_size_t((size_t)size, read_len);
  text[size] = '\0';
  return text;
}

static const char* static_tableBodyAfter(const char* text, const char* needle)
{
  const char* found = strstr(text, needle);
  TEST_ASSERT_NOT_NULL_MESSAGE(found, needle);
  const char* header = strstr(found, "\n|");
  TEST_ASSERT_NOT_NULL_MESSAGE(header, needle);
  const char* separator = strchr(header + 1, '\n');
  TEST_ASSERT_NOT_NULL_MESSAGE(separator, needle);
  TEST_ASSERT_TRUE_MESSAGE(strncmp(separator + 1, "|--", 3) == 0, needle);
  const char* body = strchr(separator + 1, '\n');
  TEST_ASSERT_NOT_NULL_MESSAGE(body, needle);
  return body + 1;
}

static bool static_nextTableRow(const char** cursor, char* row_out, size_t row_size)
{
  const char* line = *cursor;
  if (line[0] != '|')
    return false;

  const char* newline = strchr(line, '\n');
  size_t len = newline != NULL ? (size_t)(newline - line) : strlen(line);
  TEST_ASSERT_TRUE_MESSAGE(len < row_size, "a docs table row does not fit its buffer");
  memcpy(row_out, line, len);
  row_out[len] = '\0';
  *cursor = newline != NULL ? newline + 1 : line + len;
  return true;
}

static void static_tableCell(const char* row, int index, char* cell_out, size_t cell_size)
{
  const char* start = row;
  for (int i = 0; i <= index; i++)
  {
    start = strchr(start, '|');
    TEST_ASSERT_NOT_NULL_MESSAGE(start, row);
    start++;
  }
  const char* end = strchr(start, '|');
  TEST_ASSERT_NOT_NULL_MESSAGE(end, row);

  while (start < end && *start == ' ')
    start++;
  while (end > start && end[-1] == ' ')
    end--;
  size_t len = (size_t)(end - start);
  TEST_ASSERT_TRUE_MESSAGE(len < cell_size, row);
  memcpy(cell_out, start, len);
  cell_out[len] = '\0';
}

static const char* static_nextCode(const char* text, char* code_out, size_t code_size)
{
  const char* span_open = strchr(text, '`');
  if (span_open == NULL)
    return NULL;

  const char* span_close = strchr(span_open + 1, '`');
  TEST_ASSERT_NOT_NULL_MESSAGE(span_close, text);
  size_t len = (size_t)(span_close - span_open - 1);
  TEST_ASSERT_TRUE_MESSAGE(len < code_size, text);
  memcpy(code_out, span_open + 1, len);
  code_out[len] = '\0';
  return span_close + 1;
}

static bool static_isDocsPriceRead(const char* cell, unsigned int* cost_out, bool* per_id_out)
{
  *per_id_out = strstr(cell, "per id") != NULL || strstr(cell, "per hash") != NULL || strstr(cell, "per package") != NULL ||
                strstr(cell, DOCS_TIMES) != NULL;
  while (*cell == ' ' || *cell == '*')
    cell++;
  if (*cell < '0' || *cell > '9')
    return false;
  *cost_out = (unsigned int)strtoul(cell, NULL, 10);
  return true;
}

static unsigned int static_expectedCharge(unsigned int cost)
{
  return cost == 0 ? CREDIT_COST_SENTINEL : cost;
}

static bool static_isMethodAllowed(const Endpoint_t* endpoint, const char* method)
{
  const size_t slot_count = sizeof(endpoint->ma_allowedMethods) / sizeof(endpoint->ma_allowedMethods[0]);
  for (size_t i = 0; i < slot_count && endpoint->ma_allowedMethods[i] != NULL; i++)
  {
    if (strcmp(endpoint->ma_allowedMethods[i], method) == 0)
      return true;
  }
  return false;
}

static void static_fillPlaceholder(const char* target, char* path_out, size_t path_size)
{
  const char* brace_open = strchr(target, '{');
  int written;
  if (brace_open == NULL)
  {
    written = snprintf(path_out, path_size, "%s", target);
  }
  else
  {
    const char* brace_close = strchr(brace_open, '}');
    TEST_ASSERT_NOT_NULL_MESSAGE(brace_close, target);
    const char* id = strncmp(target, "/cwe_lookup/", strlen("/cwe_lookup/")) == 0 ? "CWE-79" : "CVE-2021-44228";
    written = snprintf(path_out, path_size, "%.*s%s%s", (int)(brace_open - target), target, id, brace_close + 1);
  }
  TEST_ASSERT_TRUE_MESSAGE(written > 0 && (size_t)written < path_size, target);
}

static unsigned int static_costForMcpMethod(const char* method)
{
  char body[256];
  int written = snprintf(body, sizeof(body), R"({"jsonrpc":"2.0","id":1,"method":"%s"})", method);
  TEST_ASSERT_TRUE_MESSAGE(written > 0 && (size_t)written < sizeof(body), method);
  return static_costForRequest("POST", "/mcp", body);
}

static unsigned int static_costForMcpTool(const char* tool, const char* arguments)
{
  char body[512];
  int written = snprintf(body, sizeof(body),
    R"({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"%s","arguments":%s}})",
    tool, arguments);
  TEST_ASSERT_TRUE_MESSAGE(written > 0 && (size_t)written < sizeof(body), tool);
  return static_costForRequest("POST", "/mcp", body);
}

void test_docs_api_credit_costs_match_routes_and_charges(void)
{
  char* text = static_readDocsFile(DOCS_API_PATH);
  const char* cursor = static_tableBodyAfter(text, "\n## Credit costs\n");
  const size_t method_slots = sizeof(endpoints[0].ma_allowedMethods) / sizeof(endpoints[0].ma_allowedMethods[0]);
  bool route_seen[DOCS_ROUTE_MAX] = { false };
  bool method_seen[DOCS_ROUTE_MAX][sizeof(endpoints[0].ma_allowedMethods) / sizeof(endpoints[0].ma_allowedMethods[0])] = { { false } };
  TEST_ASSERT_TRUE(endpoint_count <= DOCS_ROUTE_MAX);

  char row[DOCS_ROW_MAX];
  while (static_nextTableRow(&cursor, row, sizeof(row)))
  {
    char endpoint[DOCS_ROW_MAX];
    char price[DOCS_ROW_MAX];
    static_tableCell(row, 0, endpoint, sizeof(endpoint));
    static_tableCell(row, 1, price, sizeof(price));

    char spec[DOCS_ROW_MAX];
    const char* after_spec = static_nextCode(endpoint, spec, sizeof(spec));
    TEST_ASSERT_NOT_NULL_MESSAGE(after_spec, row);
    char method[8];
    char target[256];
    TEST_ASSERT_EQUAL_INT_MESSAGE(2, sscanf(spec, "%7s %255s", method, target), row);

    char route_path[256];
    size_t route_len = strcspn(target, "{?");
    memcpy(route_path, target, route_len);
    route_path[route_len] = '\0';
    int route_index = -1;
    for (int i = 0; i < endpoint_count; i++)
    {
      if (strcmp(endpoints[i].mp_httpPath, route_path) == 0)
        route_index = i;
    }
    TEST_ASSERT_TRUE_MESSAGE(route_index >= 0, row);
    route_seen[route_index] = true;
    TEST_ASSERT_TRUE_MESSAGE(static_isMethodAllowed(&endpoints[route_index], method), row);
    for (size_t k = 0; k < method_slots && endpoints[route_index].ma_allowedMethods[k] != NULL; k++)
    {
      if (strcmp(endpoints[route_index].ma_allowedMethods[k], method) == 0)
        method_seen[route_index][k] = true;
    }

    unsigned int cost = 0;
    bool per_id = false;
    bool has_price = static_isDocsPriceRead(price, &cost, &per_id);

    if (strcmp(route_path, "/mcp") == 0)
    {
      char rpc_method[64];
      const char* next = after_spec;
      int method_count = 0;
      while ((next = static_nextCode(next, rpc_method, sizeof(rpc_method))) != NULL)
      {
        method_count++;
        if (strcmp(rpc_method, "tools/call") == 0)
        {
          TEST_ASSERT_FALSE_MESSAGE(has_price, row);
        }
        else
        {
          TEST_ASSERT_TRUE_MESSAGE(has_price, row);
          TEST_ASSERT_EQUAL_UINT_MESSAGE(static_expectedCharge(cost), static_costForMcpMethod(rpc_method), row);
        }
      }
      TEST_ASSERT_TRUE_MESSAGE(method_count > 0, row);
      if (strstr(endpoint, "notifications") != NULL)
      {
        TEST_ASSERT_TRUE_MESSAGE(has_price, row);
        TEST_ASSERT_EQUAL_UINT_MESSAGE(static_expectedCharge(cost), static_costForRequest("POST", "/mcp", DOCS_NOTIFICATION_BODY), row);
      }
      continue;
    }

    TEST_ASSERT_TRUE_MESSAGE(has_price, row);
    if (per_id)
    {
      TEST_ASSERT_EQUAL_STRING_MESSAGE("POST", method, row);
      TEST_ASSERT_EQUAL_UINT_MESSAGE(cost * DOCS_BULK_ID_COUNT, static_costForRequest("POST", route_path, static_docsBulkBodyFor(&endpoints[route_index])), row);
      continue;
    }

    if (strcmp(method, "POST") == 0)
    {
      TEST_ASSERT_EQUAL_INT_MESSAGE(ENDPOINT_COST_FLAT, endpoints[route_index].m_costRule, row);
      TEST_ASSERT_TRUE_MESSAGE(endpoints[route_index].m_paramCount == 0 || endpoint_hasRestBodyParam(&endpoints[route_index]) || endpoint_hasRawBodyParam(&endpoints[route_index]), row);
      TEST_ASSERT_EQUAL_UINT_MESSAGE(static_expectedCharge(cost), static_costForRequest("POST", route_path, "{}"), row);
      continue;
    }

    TEST_ASSERT_EQUAL_STRING_MESSAGE("GET", method, row);
    char path[256];
    static_fillPlaceholder(target, path, sizeof(path));
    TEST_ASSERT_EQUAL_UINT_MESSAGE(static_expectedCharge(cost), static_costForPath(path), row);
  }

  for (int i = 0; i < endpoint_count; i++)
  {
    TEST_ASSERT_TRUE_MESSAGE(route_seen[i], endpoints[i].mp_httpPath);
    for (size_t k = 0; k < method_slots && endpoints[i].ma_allowedMethods[k] != NULL; k++)
      TEST_ASSERT_TRUE_MESSAGE(method_seen[i][k], endpoints[i].mp_httpPath);
  }
  free(text);
}

void test_docs_mcp_credit_costs_match_tools_and_charges(void)
{
  const char* list_body = R"({"jsonrpc":"2.0","id":1,"method":"tools/list"})";
  char* catalogue = NULL;
  int status = 0;
  TEST_ASSERT_TRUE(mcp_dispatch(list_body, strlen(list_body), NULL, &catalogue, &status, g_conn, &TEST_FULL_CHARGE, NULL));
  TEST_ASSERT_NOT_NULL(catalogue);

  char* text = static_readDocsFile(DOCS_MCP_PATH);
  const char* cursor = static_tableBodyAfter(text, "\n| Request | Credit cost |\n");
  char docs_tools[DOCS_TOOL_MAX][64];
  int  docs_tool_count = 0;

  char row[DOCS_ROW_MAX];
  while (static_nextTableRow(&cursor, row, sizeof(row)))
  {
    char request[DOCS_ROW_MAX];
    char price[DOCS_ROW_MAX];
    static_tableCell(row, 0, request, sizeof(request));
    static_tableCell(row, 1, price, sizeof(price));

    unsigned int cost = 0;
    bool per_id = false;
    TEST_ASSERT_TRUE_MESSAGE(static_isDocsPriceRead(price, &cost, &per_id), row);

    const char* arrow = strstr(request, DOCS_ARROW);
    if (arrow == NULL)
    {
      char rpc_method[64];
      const char* next = request;
      while ((next = static_nextCode(next, rpc_method, sizeof(rpc_method))) != NULL)
        TEST_ASSERT_EQUAL_UINT_MESSAGE(static_expectedCharge(cost), static_costForMcpMethod(rpc_method), row);
      if (strstr(request, "notifications") != NULL)
        TEST_ASSERT_EQUAL_UINT_MESSAGE(static_expectedCharge(cost), static_costForRequest("POST", "/mcp", DOCS_NOTIFICATION_BODY), row);
      continue;
    }

    char tools[DOCS_ROW_MAX];
    const char* after_arrow = arrow + strlen(DOCS_ARROW);
    size_t tools_len = strcspn(after_arrow, "(");
    memcpy(tools, after_arrow, tools_len);
    tools[tools_len] = '\0';

    char tool[64];
    const char* next = tools;
    while ((next = static_nextCode(next, tool, sizeof(tool))) != NULL)
    {
      char needle[96];
      int written = snprintf(needle, sizeof(needle), R"("name":"%s")", tool);
      TEST_ASSERT_TRUE_MESSAGE(written > 0 && (size_t)written < sizeof(needle), tool);
      TEST_ASSERT_NOT_NULL_MESSAGE(strstr(catalogue, needle), tool);
      unsigned int expected = per_id ? cost * DOCS_BULK_ID_COUNT : static_expectedCharge(cost);
      const Endpoint_t* tool_row = endpoint_findByMcpName(tool);
      TEST_ASSERT_NOT_NULL_MESSAGE(tool_row, tool);
      TEST_ASSERT_EQUAL_UINT_MESSAGE(expected, static_costForMcpTool(tool, static_docsBulkBodyFor(tool_row)), tool);

      TEST_ASSERT_TRUE_MESSAGE(docs_tool_count < DOCS_TOOL_MAX, row);
      written = snprintf(docs_tools[docs_tool_count], sizeof(docs_tools[0]), "%s", tool);
      TEST_ASSERT_TRUE_MESSAGE(written > 0 && (size_t)written < sizeof(docs_tools[0]), tool);
      docs_tool_count++;
    }
  }

  const char* name_key = catalogue;
  int catalogue_tool_count = 0;
  while ((name_key = strstr(name_key, R"("name":")")) != NULL)
  {
    name_key += strlen(R"("name":")");
    char name[64];
    size_t name_len = strcspn(name_key, "\"");
    TEST_ASSERT_TRUE(name_len < sizeof(name));
    memcpy(name, name_key, name_len);
    name[name_len] = '\0';

    bool named = false;
    for (int i = 0; i < docs_tool_count; i++)
    {
      if (strcmp(docs_tools[i], name) == 0)
        named = true;
    }
    TEST_ASSERT_TRUE_MESSAGE(named, name);
    catalogue_tool_count++;
  }
  TEST_ASSERT_TRUE(catalogue_tool_count > 0);
  free(text);
  free(catalogue);
}

void test_docs_mcp_405_prices_match_the_server(void)
{
  static const char* const docs_paths[] = { DOCS_API_PATH, DOCS_MCP_PATH };
  static const char* const methods[]    = { "GET", "DELETE" };
  const char* sentence = "`GET /mcp` and `DELETE /mcp` answer `405` and cost ";

  for (size_t m = 0; m < sizeof(methods) / sizeof(methods[0]); m++)
  {
    unsigned int cost  = static_costForRequest(methods[m], "/mcp", "");
    unsigned int price = cost == CREDIT_COST_SENTINEL ? 0u : cost;
    for (size_t p = 0; p < sizeof(docs_paths) / sizeof(docs_paths[0]); p++)
    {
      char* text = static_readDocsFile(docs_paths[p]);
      const char* found = strstr(text, sentence);
      TEST_ASSERT_NOT_NULL_MESSAGE(found, docs_paths[p]);
      const char* number = found + strlen(sentence);
      char* number_end = NULL;
      unsigned long docs_price = strtoul(number, &number_end, 10);
      TEST_ASSERT_TRUE_MESSAGE(number_end != number, docs_paths[p]);
      TEST_ASSERT_EQUAL_UINT_MESSAGE(price, (unsigned int)docs_price, docs_paths[p]);
      free(text);
    }
  }

  const char* other_sentence = "Any other HTTP method but `POST` answers `405` and costs ";
  unsigned int put_cost = static_costForRequest("PUT", "/mcp", "");
  char* mcp_text = static_readDocsFile(DOCS_MCP_PATH);
  const char* other = strstr(mcp_text, other_sentence);
  TEST_ASSERT_NOT_NULL_MESSAGE(other, DOCS_MCP_PATH);
  const char* other_number = other + strlen(other_sentence);
  char* other_number_end = NULL;
  unsigned long other_docs_price = strtoul(other_number, &other_number_end, 10);
  TEST_ASSERT_TRUE_MESSAGE(other_number_end != other_number, DOCS_MCP_PATH);
  TEST_ASSERT_EQUAL_UINT_MESSAGE(put_cost, (unsigned int)other_docs_price, DOCS_MCP_PATH);
  free(mcp_text);
}

