void test_docs_mcp_instructions_match_the_handshake(void)
{
  const char* body = R"({"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-11-25"}})";
  char* answer = NULL;
  int status = 0;
  TEST_ASSERT_TRUE(mcp_dispatch(body, strlen(body), NULL, &answer, &status, g_conn, &TEST_FULL_CHARGE, NULL));
  TEST_ASSERT_NOT_NULL(answer);
  const char* key = R"("instructions":")";
  const char* code_value = strstr(answer, key);
  TEST_ASSERT_NOT_NULL_MESSAGE(code_value, answer);
  code_value += strlen(key);
  size_t code_len = strcspn(code_value, "\"");

  char* text = static_readDocsFile(DOCS_MCP_PATH);
  int copies = 0;
  for (const char* cursor = text; (cursor = strstr(cursor, key)) != NULL; copies++)
  {
    cursor += strlen(key);
    TEST_ASSERT_EQUAL_size_t_MESSAGE(code_len, strcspn(cursor, "\""), cursor);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, strncmp(code_value, cursor, code_len), cursor);
  }
  TEST_ASSERT_EQUAL_INT(2, copies);
  free(text);
  free(answer);
}

void test_docs_web_files_table_matches_the_served_files(void)
{
  char* text = static_readDocsFile(DOCS_API_PATH);
  const char* cursor = static_tableBodyAfter(text, "\n## Web files\n");
  char row[DOCS_ROW_MAX];
  int row_count = 0;
  while (static_nextTableRow(&cursor, row, sizeof(row)))
  {
    char cell[DOCS_ROW_MAX];
    char path[DOCS_ROUTE_MAX];
    char content_type[DOCS_ROUTE_MAX];
    char cache_control[DOCS_ROUTE_MAX];
    static_tableCell(row, 0, cell, sizeof(cell));
    TEST_ASSERT_NOT_NULL_MESSAGE(static_nextCode(cell, path, sizeof(path)), row);
    static_tableCell(row, 1, cell, sizeof(cell));
    TEST_ASSERT_NOT_NULL_MESSAGE(static_nextCode(cell, content_type, sizeof(content_type)), row);
    static_tableCell(row, 2, cell, sizeof(cell));
    TEST_ASSERT_NOT_NULL_MESSAGE(static_nextCode(cell, cache_control, sizeof(cache_control)), row);

    const PagesFile_t* file = pages_findServedFile(path);
    TEST_ASSERT_NOT_NULL_MESSAGE(file, row);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(file->mp_contentType,  content_type,  row);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(file->mp_cacheControl, cache_control, row);
    row_count++;
  }
  TEST_ASSERT_EQUAL_INT(pages_sourceCount, row_count);
  free(text);
}

#define PAGE_LIST_ROW_MAX 64

static const char* const ROUTE_LIST_EXEMPT_PATHS[] = { "/webhook_lemonsqueezy", "/webhook_nowpayments", "/api_key_claim", "/crypto_checkout" };

static bool static_isRouteListExempt(const char* http_path)
{
  for (size_t i = 0; i < sizeof(ROUTE_LIST_EXEMPT_PATHS) / sizeof(ROUTE_LIST_EXEMPT_PATHS[0]); i++)
    if (strcmp(http_path, ROUTE_LIST_EXEMPT_PATHS[i]) == 0)
      return true;
  return false;
}

static char* static_pageText(const char* http_path)
{
  const PagesFile_t* file = pages_findServedFile(http_path);
  TEST_ASSERT_NOT_NULL_MESSAGE(file, http_path);
  char* text = (char*)malloc(file->m_bodyByteCount + 1);
  TEST_ASSERT_NOT_NULL(text);
  memcpy(text, file->mp_body, file->m_bodyByteCount);
  text[file->m_bodyByteCount] = '\0';
  return text;
}

static int static_listedRow(const char* listed)
{
  char text[DOCS_ROW_MAX];
  size_t len = 0;
  for (const char* at = listed; *at != '\0' && len + 1 < sizeof(text); )
  {
    if (strncmp(at, "&amp;", 5) == 0) { text[len++] = '&'; at += 5; }
    else text[len++] = *at++;
  }
  text[len] = '\0';

  char* query = strchr(text, '?');
  if (query != NULL)
    *query++ = '\0';
  char* segment = strchr(text, '{');
  bool has_segment = segment != NULL;
  if (has_segment)
    *segment = '\0';

  int row = -1;
  for (int i = 0; i < endpoint_count && row < 0; i++)
  {
    if (endpoints[i].m_hasPathSegment == has_segment && strcmp(endpoints[i].mp_httpPath, text) == 0)
      row = i;
  }
  TEST_ASSERT_TRUE_MESSAGE(row >= 0, listed);

  for (char* name = query; name != NULL && *name != '\0'; )
  {
    char* next = strchr(name, '&');
    if (next != NULL)
      *next++ = '\0';
    char* value = strchr(name, '=');
    if (value != NULL)
      *value = '\0';
    bool is_param = false;
    for (int p = 0; p < endpoints[row].m_paramCount && !is_param; p++)
      is_param = strcmp(endpoints[row].mp_params[p].mp_spec->mp_name, name) == 0;
    TEST_ASSERT_TRUE_MESSAGE(is_param, listed);
    name = next;
  }
  return row;
}

static void static_readListedRoutes(const char* text, int seen_out[PAGE_LIST_ROW_MAX])
{
  static const char method_start[] = "<span class=\"method ";
  static const char path_start[] = "<span class=\"endpoint-path\">";
  for (const char* at = strstr(text, method_start); at != NULL; at = strstr(at + 1, method_start))
  {
    char method[16];
    const char* method_text = strchr(at, '>') + 1;
    snprintf(method, sizeof(method), "%.*s", (int)(strstr(method_text, "</span>") - method_text), method_text);
    const char* path_at = strstr(at, path_start);
    TEST_ASSERT_NOT_NULL(path_at);
    path_at += strlen(path_start);
    char listed[DOCS_ROW_MAX];
    snprintf(listed, sizeof(listed), "%.*s", (int)(strstr(path_at, "</span>") - path_at), path_at);
    int row = static_listedRow(listed);
    TEST_ASSERT_TRUE_MESSAGE(static_isMethodAllowed(&endpoints[row], method), listed);
    seen_out[row]++;
  }
}

void test_pages_list_every_route_once_and_no_other(void)
{
  TEST_ASSERT_TRUE(endpoint_count <= PAGE_LIST_ROW_MAX);

  char* home = static_pageText("/");
  int home_seen[PAGE_LIST_ROW_MAX] = { 0 };
  char* costs = strstr(home, "id=\"costs\"");
  TEST_ASSERT_NOT_NULL(costs);
  *costs = '\0';
  static_readListedRoutes(home, home_seen);
  for (int i = 0; i < endpoint_count; i++)
    TEST_ASSERT_EQUAL_INT_MESSAGE(static_isRouteListExempt(endpoints[i].mp_httpPath) ? 0 : 1, home_seen[i], endpoints[i].mp_httpPath);
  free(home);

  char* llms = static_pageText("/llms.txt");
  int llms_seen[PAGE_LIST_ROW_MAX] = { 0 };
  char* section = strstr(llms, "\n## Endpoints\n");
  TEST_ASSERT_NOT_NULL(section);
  char* section_end = strstr(section, "\n## MCP");
  TEST_ASSERT_NOT_NULL(section_end);
  *section_end = '\0';
  for (char* line = strstr(section, "\n- "); line != NULL; line = strstr(line + 1, "\n- "))
  {
    char method[16];
    char listed[DOCS_ROW_MAX];
    TEST_ASSERT_EQUAL_INT_MESSAGE(2, sscanf(line + 3, "%15s %511s", method, listed), line);
    size_t listed_len = strlen(listed);
    TEST_ASSERT_TRUE_MESSAGE(listed_len > 1 && listed[listed_len - 1] == ':', line);
    listed[listed_len - 1] = '\0';
    int row = static_listedRow(listed);
    TEST_ASSERT_TRUE_MESSAGE(static_isMethodAllowed(&endpoints[row], method), listed);
    llms_seen[row]++;
  }
  for (int i = 0; i < endpoint_count; i++)
    TEST_ASSERT_EQUAL_INT_MESSAGE((endpoints[i].m_isMcpEndpoint || static_isRouteListExempt(endpoints[i].mp_httpPath)) ? 0 : 1, llms_seen[i], endpoints[i].mp_httpPath);
  free(llms);

  static const char* const capability_pages[] = {
    "/cve-api", "/package-vulnerability-api", "/domain-monitoring-api", "/ip-intelligence-api",
    "/security-monitoring-api",
  };
  for (size_t i = 0; i < sizeof(capability_pages) / sizeof(capability_pages[0]); i++)
  {
    char* page = static_pageText(capability_pages[i]);
    int page_seen[PAGE_LIST_ROW_MAX] = { 0 };
    static_readListedRoutes(page, page_seen);
    free(page);
  }
}

void test_mcp_doc_tool_section_price_matches_row(void)
{
  char* text = static_readDocsFile(DOCS_MCP_PATH);
  int checked = 0;
  for (char* section = strstr(text, "\n### `"); section != NULL; section = strstr(section + 1, "\n### `"))
  {
    char tool[64];
    if (sscanf(section + 6, "%63[^`]", tool) != 1)
      continue;
    const Endpoint_t* endpoint = endpoint_findByMcpName(tool);
    if (endpoint == NULL)
      continue;
    const char* section_end = strstr(section + 1, "\n#");
    for (const char* line = strchr(section + 1, '\n'); line != NULL && (section_end == NULL || line < section_end); line = strchr(line + 1, '\n'))
    {
      unsigned int count = 0;
      char word[8];
      if (sscanf(line + 1, "%u %7s", &count, word) == 2 && strncmp(word, "credit", 6) == 0)
      {
        TEST_ASSERT_EQUAL_UINT_MESSAGE(endpoint->m_creditCost, count, tool);
        checked++;
      }
    }
  }
  TEST_ASSERT_TRUE(checked >= 3);
  free(text);
}

