  const char* api_license_at = strstr(api_section, "| `license`");
  TEST_ASSERT_TRUE(api_license_at != NULL && api_license_at < api_end);
  api_license_at = strstr(api_license_at, "Always `\"");
  TEST_ASSERT_TRUE(api_license_at != NULL && api_license_at < api_end);
  char api_license[32];
  TEST_ASSERT_EQUAL_INT(1, sscanf(api_license_at + strlen("Always `\""), "%31[^\"]", api_license));
  TEST_ASSERT_EQUAL_STRING(license, api_license);
  const char* api_max_at = strstr(api_section, "| `top_results` |");
