void test_page_credit_costs_match_the_rows(void)
{
  TEST_ASSERT_TRUE(endpoint_count <= PAGE_LIST_ROW_MAX);
  int home_priced[PAGE_LIST_ROW_MAX] = { 0 };
  int llms_priced[PAGE_LIST_ROW_MAX] = { 0 };
  char* home = static_pageText("/");
  char* costs = strstr(home, "id=\"costs\"");
  TEST_ASSERT_NOT_NULL(costs);
  char* costs_end = strstr(costs, "</section>");
  TEST_ASSERT_NOT_NULL(costs_end);
  *costs_end = '\0';
  int priced_count = 0;
  static const char method_start[] = "<span class=\"method ";
  static const char path_start[] = "<span class=\"endpoint-path\">";
  for (char* at = strstr(costs, method_start); at != NULL; at = strstr(at + 1, method_start))
  {
    char* price_text = strchr(at, '>') + 1;
    char* path_at = strstr(at, path_start) + strlen(path_start);
    if (*path_at != '/')
      continue;
    char listed[DOCS_ROW_MAX];
    snprintf(listed, sizeof(listed), "%.*s", (int)(strstr(path_at, "</span>") - path_at), path_at);
    int row = static_listedRow(listed);
    TEST_ASSERT_EQUAL_UINT_MESSAGE(endpoints[row].m_creditCost, strtoul(price_text, NULL, 10), listed);
    home_priced[row]++;
    priced_count++;
  }
  TEST_ASSERT_TRUE(priced_count >= 2);
  free(home);

  char* llms = static_pageText("/llms.txt");
  char* section = strstr(llms, "\n## Credit Costs\n");
  TEST_ASSERT_NOT_NULL(section);
  char* section_end = strstr(section, "\n## Endpoints");
  TEST_ASSERT_NOT_NULL(section_end);
  *section_end = '\0';
  int llms_priced_count = 0;
  for (char* line = strstr(section, "\n- `"); line != NULL; line = strstr(line + 1, "\n- `"))
  {
    char* call = line + 4;
    char* call_end = strchr(call, '`');
    if (call_end == NULL || strncmp(call_end, "`: ", 3) != 0)
      continue;
    char listed[DOCS_ROW_MAX];
    char* space = strchr(call, ' ');
    TEST_ASSERT_TRUE(space != NULL && space < call_end);
    snprintf(listed, sizeof(listed), "%.*s", (int)(call_end - space - 1), space + 1);
    int row = static_listedRow(listed);
    TEST_ASSERT_EQUAL_UINT_MESSAGE(endpoints[row].m_creditCost, strtoul(call_end + 3, NULL, 10), listed);
    llms_priced[row]++;
    llms_priced_count++;
  }
  TEST_ASSERT_TRUE(llms_priced_count >= 3);
  free(llms);

  for (int i = 0; i < endpoint_count; i++)
  {
    if (static_isRouteListExempt(endpoints[i].mp_httpPath))
    {
      TEST_ASSERT_EQUAL_INT_MESSAGE(0, home_priced[i] + llms_priced[i], endpoints[i].mp_httpPath);
      continue;
    }
    if (endpoints[i].m_costRule != ENDPOINT_COST_FLAT)
      continue;
    if (home_priced[i] == 0 || llms_priced[i] == 0)
      TEST_ASSERT_EQUAL_UINT_MESSAGE(1, endpoints[i].m_creditCost, endpoints[i].mp_httpPath);
  }
}

