void test_docs_mcp_tool_table_names_every_tool(void)
{
  const char* list_body = R"({"jsonrpc":"2.0","id":1,"method":"tools/list"})";
  char* catalogue = NULL;
  int status = 0;
  TEST_ASSERT_TRUE(mcp_dispatch(list_body, strlen(list_body), NULL, &catalogue, &status, g_conn, &TEST_FULL_CHARGE, NULL));
  TEST_ASSERT_NOT_NULL(catalogue);

  char* text = static_readDocsFile(DOCS_MCP_PATH);
  const char* tools_line = strstr(text, "| **Tools** |");
  TEST_ASSERT_NOT_NULL(tools_line);
  size_t tools_line_len = strcspn(tools_line, "\n");

  const char* cursor = static_tableBodyAfter(text, "\n| Tool | Required | Optional arguments | Mirrors |\n");
  int row_count = 0;
  char row[DOCS_ROW_MAX];
  while (static_nextTableRow(&cursor, row, sizeof(row)))
  {
    char cell[DOCS_ROW_MAX];
    char mirrors[DOCS_ROW_MAX];
    char tool[64];
    static_tableCell(row, 0, cell, sizeof(cell));
    static_tableCell(row, 3, mirrors, sizeof(mirrors));
    TEST_ASSERT_NOT_NULL_MESSAGE(static_nextCode(cell, tool, sizeof(tool)), row);
    char needle[96];
    snprintf(needle, sizeof(needle), R"("name":"%s")", tool);
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(catalogue, needle), tool);
    const Endpoint_t* endpoint = endpoint_findByMcpName(tool);
    TEST_ASSERT_NOT_NULL_MESSAGE(endpoint, tool);
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(mirrors, endpoint->mp_httpPath), row);
    row_count++;
  }

  int catalogue_tool_count = 0;
  for (const char* name_key = catalogue; (name_key = strstr(name_key, R"("name":")")) != NULL; catalogue_tool_count++)
  {
    name_key += strlen(R"("name":")");
    char name[64];
    size_t name_len = strcspn(name_key, "\"");
    TEST_ASSERT_TRUE(name_len < sizeof(name));
    memcpy(name, name_key, name_len);
    name[name_len] = '\0';
    char row_needle[96];
    snprintf(row_needle, sizeof(row_needle), "\n| `%s` |", name);
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(text, row_needle), name);
    char code[96];
    snprintf(code, sizeof(code), "`%s`", name);
    const char* on_line = strstr(tools_line, code);
    TEST_ASSERT_TRUE_MESSAGE(on_line != NULL && (size_t)(on_line - tools_line) < tools_line_len, name);
  }
  TEST_ASSERT_EQUAL_INT(catalogue_tool_count, row_count);
  int tools_line_backtick_count = 0;
  for (size_t i = 0; i < tools_line_len; i++)
    if (tools_line[i] == '`')
      tools_line_backtick_count++;
  TEST_ASSERT_EQUAL_INT(2 * catalogue_tool_count, tools_line_backtick_count);
  free(text);
  free(catalogue);
}

static const char* static_toolsListElement(const char* catalogue, const char* tool, size_t* len_out)
{
  char needle[96];
  int needle_len = snprintf(needle, sizeof(needle), R"({"name":"%s")", tool);
  TEST_ASSERT_TRUE_MESSAGE(needle_len > 0 && (size_t)needle_len < sizeof(needle), tool);
  const char* start = strstr(catalogue, needle);
  TEST_ASSERT_NOT_NULL_MESSAGE(start, tool);
  const char* next = strstr(start + 1, R"(,{"name":")");
  const char* end  = next != NULL ? next : strstr(start, R"(]})");
  TEST_ASSERT_NOT_NULL_MESSAGE(end, tool);
  *len_out = (size_t)(end - start);
  return start;
}

void test_docs_mcp_category_list_matches_code(void)
{
  char* text = static_readDocsFile(DOCS_MCP_PATH);
  const char* start = strstr(text, "The values are a closed set:");
  TEST_ASSERT_NOT_NULL(start);
  const char* end = strstr(start, "\n\n");
  TEST_ASSERT_NOT_NULL(end);

  const char* cursor = start;
  int category_count = 0;
  for (int category = ENDPOINT_MCP_TOOL_CATEGORY_NONE + 1; endpoint_mcpToolCategoryName((EndpointMcpToolCategory_t)category) != NULL; category++, category_count++)
  {
    const char* expected = endpoint_mcpToolCategoryName((EndpointMcpToolCategory_t)category);
    const char* open = strchr(cursor, '`');
    TEST_ASSERT_TRUE_MESSAGE(open != NULL && open < end, expected);
    const char* close = strchr(open + 1, '`');
    TEST_ASSERT_TRUE_MESSAGE(close != NULL && close < end, expected);
    TEST_ASSERT_EQUAL_size_t_MESSAGE(strlen(expected), (size_t)(close - open - 1), expected);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, strncmp(open + 1, expected, strlen(expected)), expected);
    cursor = close + 1;
  }
  TEST_ASSERT_TRUE(category_count > 0);
  const char* extra = strchr(cursor, '`');
  TEST_ASSERT_TRUE_MESSAGE(extra == NULL || extra >= end, "the docs list a category the code lacks");
  free(text);
}

void test_docs_mcp_example_entry_matches_tools_list(void)
{
  const char* list_body = R"({"jsonrpc":"2.0","id":1,"method":"tools/list"})";
  char* catalogue = NULL;
  int status = 0;
  TEST_ASSERT_TRUE(mcp_dispatch(list_body, strlen(list_body), NULL, &catalogue, &status, g_conn, &TEST_FULL_CHARGE, NULL));
  TEST_ASSERT_NOT_NULL(catalogue);

  size_t element_len = 0;
  const char* element = static_toolsListElement(catalogue, "kev_lookup", &element_len);
  const char* key = R"("description":")";
  const char* value = (const char*)memmem(element, element_len, key, strlen(key));
  TEST_ASSERT_NOT_NULL(value);
  value += strlen(key);
  const char* value_end = value;
  while (value_end < element + element_len && *value_end != '"')
    value_end += (*value_end == '\\') ? 2 : 1;
  TEST_ASSERT_TRUE(value_end < element + element_len);

  static char live[4096];
  int live_len = snprintf(live, sizeof(live), "%.*s\xE2\x80\xA6%.*s", (int)(value - element), element, (int)(element + element_len - value_end), value_end);
  TEST_ASSERT_TRUE(live_len > 0 && (size_t)live_len < sizeof(live));

  char* text = static_readDocsFile(DOCS_MCP_PATH);
  const char* anchor = strstr(text, "One entry, with its description shortened to");
  TEST_ASSERT_NOT_NULL(anchor);
  const char* fence = strstr(anchor, "```json\n");
  TEST_ASSERT_NOT_NULL(fence);
  const char* line = fence + strlen("```json\n");
  size_t line_len = strcspn(line, "\n");
  TEST_ASSERT_EQUAL_size_t_MESSAGE((size_t)live_len, line_len, live);
  TEST_ASSERT_EQUAL_INT_MESSAGE(0, memcmp(line, live, line_len), live);
  free(text);
  free(catalogue);
}

void test_docs_mcp_effect_table_hints_match_tools_list(void)
{
  const char* list_body = R"({"jsonrpc":"2.0","id":1,"method":"tools/list"})";
  char* catalogue = NULL;
  int status = 0;
  TEST_ASSERT_TRUE(mcp_dispatch(list_body, strlen(list_body), NULL, &catalogue, &status, g_conn, &TEST_FULL_CHARGE, NULL));
  TEST_ASSERT_NOT_NULL(catalogue);

  char* text = static_readDocsFile(DOCS_MCP_PATH);
  const char* cursor = static_tableBodyAfter(text, "\n| Effect | Tools | Hints |\n");
  static const char* const TOOL_OF_ROW[] = { "kev_lookup", "watchlist_events", "watchlist_edit" };
  for (size_t row_index = 0; row_index < sizeof(TOOL_OF_ROW) / sizeof(TOOL_OF_ROW[0]); row_index++)
  {
    char row[DOCS_ROW_MAX];
    TEST_ASSERT_TRUE(static_nextTableRow(&cursor, row, sizeof(row)));
    char hints[DOCS_ROW_MAX];
    static_tableCell(row, 2, hints, sizeof(hints));

    char expected[DOCS_ROW_MAX];
    size_t expected_len = 0;
    expected[expected_len++] = '{';
    const char* read = hints;
    int hint_count = 0;
    char name[64];
    while ((read = static_nextCode(read, name, sizeof(name))) != NULL)
    {
      while (*read == ' ')
        read++;
      size_t word_len = 0;
      if (strncmp(read, "true", 4) == 0)
        word_len = 4;
      else if (strncmp(read, "false", 5) == 0)
        word_len = 5;
      TEST_ASSERT_TRUE_MESSAGE(word_len > 0, row);
      size_t room = sizeof(expected) - expected_len - 1;
      int written = snprintf(expected + expected_len, room, "%s\"%s\":%.*s", hint_count > 0 ? "," : "", name, (int)word_len, read);
      TEST_ASSERT_TRUE_MESSAGE(written > 0 && (size_t)written < room, row);
      expected_len += (size_t)written;
      read += word_len;
      hint_count++;
    }
    TEST_ASSERT_TRUE_MESSAGE(hint_count > 0, row);
    expected[expected_len++] = '}';
    expected[expected_len] = '\0';

    size_t element_len = 0;
    const char* element = static_toolsListElement(catalogue, TOOL_OF_ROW[row_index], &element_len);
    const char* annotations_key = R"("annotations":)";
    const char* annotations = (const char*)memmem(element, element_len, annotations_key, strlen(annotations_key));
    TEST_ASSERT_NOT_NULL_MESSAGE(annotations, TOOL_OF_ROW[row_index]);
    annotations += strlen(annotations_key);
    const char* open_world_key = R"(,"openWorldHint":)";
    const char* open_world = (const char*)memmem(annotations, (size_t)(element + element_len - annotations), open_world_key, strlen(open_world_key));
    TEST_ASSERT_NOT_NULL_MESSAGE(open_world, TOOL_OF_ROW[row_index]);
    char live[DOCS_ROW_MAX];
    int live_len = snprintf(live, sizeof(live), "%.*s}", (int)(open_world - annotations), annotations);
    TEST_ASSERT_TRUE_MESSAGE(live_len > 0 && (size_t)live_len < sizeof(live), TOOL_OF_ROW[row_index]);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(expected, live, TOOL_OF_ROW[row_index]);
  }
  free(text);
  free(catalogue);
}

