static int static_countMibCopies(const char* text, const char* path)
{
  int mib_count = 0;
  for (const char* f = strstr(text, " MiB"); f; f = strstr(f + 1, " MiB"))
  {
    const char* digits = f;
    while (digits > text && digits[-1] >= '0' && digits[-1] <= '9')
      digits--;
    if (digits == f || static_docsBulkSectionIndexAt(text, f, DOCS_MCP_BULK_SECTIONS, "\n### ") >= 0)
      continue;
    TEST_ASSERT_EQUAL_UINT_MESSAGE(ENDPOINT_MAX_BODY_BYTE_COUNT / (1024u * 1024u), (unsigned)strtoul(digits, NULL, 10), path);
    mib_count++;
  }
  return mib_count;
}

