void test_rest_text_parameters_take_the_endpoint_table_length(void)
{
  for (int i = 0; i < endpoint_count; i++)
  {
    const Endpoint_t* endpoint = &endpoints[i];
    for (int j = 0; j < endpoint->m_paramCount; j++)
    {
      const EndpointParam_t* param = &endpoint->mp_params[j];
      const EndpointParamSpec_t* spec = param->mp_spec;
      if (!(param->m_sources & ENDPOINT_PARAM_SRC_REST_QUERY) || !static_isTextParam(spec))
        continue;

      char message[64];
      int written = snprintf(message, sizeof(message), "%s is too long", spec->mp_name);
      TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(message));
      for (size_t len = spec->m_maxLen; len <= spec->m_maxLen + 1; len++)
      {
        char value[512];
        TEST_ASSERT_TRUE(len < sizeof(value));
        memset(value, 'a', len);
        value[len] = '\0';
        char req[1024];
        static_restRequestFor(endpoint, param, value, req, sizeof(req));
        char buf[RESP_BUF];
        static_callRequestHandle(req, buf, sizeof(buf));
        TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), req);
        if (len == spec->m_maxLen)
          TEST_ASSERT_NULL_MESSAGE(strstr(buf, message), req);
        else
        {
          TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 400"), req);
          TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, message), req);
        }
      }
    }
  }
}

void test_mcp_optional_text_arguments_take_the_endpoint_table_length(void)
{
  for (int i = 0; i < endpoint_count; i++)
  {
    const Endpoint_t* endpoint = &endpoints[i];
    for (int j = 0; j < endpoint->m_paramCount; j++)
    {
      const EndpointParam_t* param = &endpoint->mp_params[j];
      const EndpointParamSpec_t* spec = param->mp_spec;
      if (!(param->m_sources & ENDPOINT_PARAM_SRC_MCP_ARG) || param->m_isRequired || !static_isTextParam(spec))
        continue;

      char message[96];
      int written = snprintf(message, sizeof(message), "%s is too long", spec->mp_name);
      TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(message));
      for (size_t len = spec->m_maxLen; len <= spec->m_maxLen + 1; len++)
      {
        char value[512];
        TEST_ASSERT_TRUE(len + 2 < sizeof(value));
        value[0] = '"';
        memset(value + 1, 'a', len);
        value[len + 1] = '"';
        value[len + 2] = '\0';
        char* answer = static_mcpToolCallFor(endpoint, param, value);
        if (len == spec->m_maxLen)
          TEST_ASSERT_NULL_MESSAGE(strstr(answer, message), message);
        else
        {
          TEST_ASSERT_NOT_NULL_MESSAGE(strstr(answer, R"("isError":true)"), message);
          TEST_ASSERT_NOT_NULL_MESSAGE(strstr(answer, message), message);
        }
        free(answer);
      }
    }
  }
}

void test_rest_numeric_bounds_are_the_endpoint_table_bounds(void)
{
  for (int i = 0; i < endpoint_count; i++)
  {
    const Endpoint_t* endpoint = &endpoints[i];
    for (int j = 0; j < endpoint->m_paramCount; j++)
    {
      const EndpointParam_t* param = &endpoint->mp_params[j];
      const EndpointParamSpec_t* spec = param->mp_spec;
      if (!(param->m_sources & ENDPOINT_PARAM_SRC_REST_QUERY) || (spec->m_type != ENDPOINT_PARAM_TYPE_INT && spec->m_type != ENDPOINT_PARAM_TYPE_DOUBLE))
        continue;

      for (int step = -1; step <= 2; step++)
      {
        char value[32];
        static_formatBoundProbe(spec, step, value, sizeof(value));
        char req[512];
        static_restRequestFor(endpoint, param, value, req, sizeof(req));
        char buf[RESP_BUF];
        static_callRequestHandle(req, buf, sizeof(buf));
        TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), req);
        if (step == 0 || step == 1)
          TEST_ASSERT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 400"), req);
        else
        {
          TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 400"), req);
          char message[256];
          static_errorMessageOf(buf, message, sizeof(message));
          TEST_ASSERT_EQUAL_INT_MESSAGE(0, strncmp(message, spec->mp_name, strlen(spec->mp_name)), req);
        }
      }
    }
  }
}

