void test_rest_include_rejected_reaches_its_own_field(void)
{
  g_stub_CVESEARCH_status       = DB_OK;
  g_stub_CVELEADING_status      = DB_OK;
  g_stub_CVETRIAGE_status       = DB_OK;
  g_stub_PRODUCTEXPOSURE_status = DB_OK;
  char buf[RESP_BUF];

  for (int is_rejected_included = 1; is_rejected_included >= 0; is_rejected_included--)
  {
    const char* query = is_rejected_included ? "?include_rejected=true" : "?include_rejected=false";
    char path[96];

    snprintf(path, sizeof(path), "/cve_search%s", query);
    static_restGet(path, buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 200"), path);
    TEST_ASSERT_TRUE_MESSAGE(g_stub_CVESEARCH_last_params.m_isRejectedIncluded == (bool)is_rejected_included, path);
    TEST_ASSERT_FALSE_MESSAGE(g_stub_CVESEARCH_last_params.m_hasNucleiTemplate, path);
    TEST_ASSERT_FALSE_MESSAGE(g_stub_CVESEARCH_last_params.m_knownRansomware, path);

    snprintf(path, sizeof(path), "/cve_leading%s", query);
    static_restGet(path, buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 200"), path);
    TEST_ASSERT_TRUE_MESSAGE(g_stub_CVELEADING_last_params.m_isRejectedIncluded == (bool)is_rejected_included, path);
    TEST_ASSERT_FALSE_MESSAGE(g_stub_CVELEADING_last_params.m_hasNucleiTemplate, path);
    TEST_ASSERT_FALSE_MESSAGE(g_stub_CVELEADING_last_params.m_knownRansomware, path);

    snprintf(path, sizeof(path), "/cve_triage%s", query);
    static_restGet(path, buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 200"), path);
    TEST_ASSERT_TRUE_MESSAGE(g_stub_CVETRIAGE_last_params.m_isRejectedIncluded == (bool)is_rejected_included, path);

    snprintf(path, sizeof(path), "/product_exposure?vendor=apache&product=log4j&%s", query + 1);
    static_restGet(path, buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 200"), path);
    TEST_ASSERT_TRUE_MESSAGE(g_stub_PRODUCTEXPOSURE_last_params.m_isRejectedIncluded == (bool)is_rejected_included, path);
    TEST_ASSERT_EQUAL_STRING_MESSAGE("apache", g_stub_PRODUCTEXPOSURE_last_params.ma_vendor, path);
    TEST_ASSERT_EQUAL_STRING_MESSAGE("log4j", g_stub_PRODUCTEXPOSURE_last_params.ma_product, path);
    TEST_ASSERT_EQUAL_STRING_MESSAGE("", g_stub_PRODUCTEXPOSURE_last_params.ma_version, path);
  }
  TEST_ASSERT_EQUAL_INT(2, g_stub_CVESEARCH_call_count);
  TEST_ASSERT_EQUAL_INT(2, g_stub_CVELEADING_call_count);
  TEST_ASSERT_EQUAL_INT(2, g_stub_CVETRIAGE_call_count);
}

