static void static_rowRequestWithQuery(const Endpoint_t* endpoint, const char* query, char* req, size_t req_size)
{
  const char* method  = endpoint->ma_allowedMethods[0];
  const char* path_id = "";
  for (int i = 0; i < endpoint->m_paramCount; i++)
  {
    if (endpoint->mp_params[i].m_sources & ENDPOINT_PARAM_SRC_REST_PATH_SEGMENT)
      path_id = static_wellFormedPathIdFor(endpoint->mp_params[i].mp_spec);
  }
  const char* body = "";
  if (strcmp(method, "POST") == 0)
    body = endpoint->m_isMcpEndpoint ? R"({"jsonrpc":"2.0","id":1,"method":"tools/list"})" : R"({"cve_ids":["CVE-2021-44228"]})";

  int written = snprintf(req, req_size, "%s %s%s?%s HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\n\r\n%s",
                         method, endpoint->mp_httpPath, path_id, query, body);
  TEST_ASSERT_TRUE_MESSAGE(written > 0 && (size_t)written < req_size, endpoint->mp_httpPath);
}

static void static_unknownParamNameMessage(const Endpoint_t* endpoint, char* out, size_t out_size)
{
  int used = snprintf(out, out_size, "unknown query parameter; this endpoint takes");
  bool has_query_param = false;
  for (int i = 0; i < endpoint->m_paramCount; i++)
  {
    if (!(endpoint->mp_params[i].m_sources & ENDPOINT_PARAM_SRC_REST_QUERY))
      continue;
    used += snprintf(out + used, out_size - (size_t)used, "%s%s", has_query_param ? ", " : " ", endpoint->mp_params[i].mp_spec->mp_name);
    TEST_ASSERT_TRUE_MESSAGE((size_t)used < out_size, endpoint->mp_httpPath);
    has_query_param = true;
  }
  if (!has_query_param)
    snprintf(out, out_size, "this endpoint takes no query parameters");
}

void test_rest_param_name_refusals_answer_before_the_handler(void)
{
  g_stub_CVELOOKUP_status  = DB_OK;
  g_stub_CVESEARCH_status  = DB_OK;
  g_stub_CVELEADING_status = DB_OK;
  g_stub_CVETRIAGE_status  = DB_OK;
  for (int i = 0; i < endpoint_count; i++)
  {
    const Endpoint_t* endpoint = &endpoints[i];
    char unknown_message[256];
    static_unknownParamNameMessage(endpoint, unknown_message, sizeof(unknown_message));
    const struct { const char* mp_query; const char* mp_message; } cases[] = {
      { "zz=1",           unknown_message                             },
      { "incl%75de=ghsa", unknown_message                             },
      { "%00=1",          unknown_message                             },
      { "vendor",         "every query parameter must be name=value" },
      { "=x",             "every query parameter must be name=value" },
    };
    for (size_t j = 0; j < sizeof(cases) / sizeof(cases[0]); j++)
    {
      char req[1024];
      char buf[RESP_BUF];
      static_rowRequestWithQuery(endpoint, cases[j].mp_query, req, sizeof(req));
      static_callRequestHandle(req, buf, sizeof(buf));
      static_assertRefusedWith(buf, cases[j].mp_message, req);
    }

    for (int k = 0; k < endpoint->m_paramCount; k++)
    {
      const char* name = endpoint->mp_params[k].mp_spec->mp_name;
      if (!(endpoint->mp_params[k].m_sources & ENDPOINT_PARAM_SRC_REST_QUERY))
        continue;
      char query[128];
      char message[128];
      char req[1024];
      char buf[RESP_BUF];
      snprintf(query, sizeof(query), "%s=x&%s=x", name, name);
      snprintf(message, sizeof(message), "%s appears more than once", name);
      static_rowRequestWithQuery(endpoint, query, req, sizeof(req));
      static_callRequestHandle(req, buf, sizeof(buf));
      static_assertRefusedWith(buf, message, req);
    }
  }
  TEST_ASSERT_EQUAL_INT(0, g_stub_CVELOOKUP_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CVELOOKUPBULK_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CVESEARCH_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CVELEADING_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CVETRIAGE_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CVELOOKUPGHSA_call_count);
}

