void test_rest_param_name_refusal_pays_the_row_price(void)
{
  const char* three_ids = R"({"cve_ids":["CVE-2021-44228","CVE-2022-12345","CVE-2023-99999"]})";
  const char* bulk_call = R"({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"cve_lookup_bulk","arguments":{"cve_ids":["CVE-2021-44228","CVE-2022-12345","CVE-2023-99999"]}}})";

  TEST_ASSERT_EQUAL_UINT(2, static_costForRequest("POST", "/image_inspect?foo=1", "x"));
  TEST_ASSERT_EQUAL_UINT(CREDIT_COST_SENTINEL, static_costForPath("/health?_=1"));
  TEST_ASSERT_EQUAL_UINT(3, static_costForRequest("POST", "/cve_lookup_bulk", three_ids));
  TEST_ASSERT_EQUAL_UINT(1, static_costForRequest("POST", "/cve_lookup_bulk?x=1", three_ids));
  TEST_ASSERT_EQUAL_UINT(3, static_costForRequest("POST", "/mcp", bulk_call));
  TEST_ASSERT_EQUAL_UINT(1, static_costForRequest("POST", "/mcp?x=1", bulk_call));
}

