void test_old_parameter_names_are_unknown(void)
{
  g_stub_CVELOOKUP_status = DB_OK;
  g_stub_CVETRIAGE_status = DB_OK;
  TEST_ASSERT_EQUAL_UINT(1, static_costForPath("/cve_lookup/CVE-2021-44228?ghsa=true"));
  TEST_ASSERT_EQUAL_UINT(1, static_costForPath("/cve_triage?min_score=70"));

  char buf[RESP_BUF];
  static_restGet("/cve_lookup/CVE-2021-44228?ghsa=true", buf, sizeof(buf));
  static_assertRefusedWith(buf, "unknown query parameter; this endpoint takes include_ghsa", "/cve_lookup/CVE-2021-44228?ghsa=true");
  static_restGet("/cve_triage?min_score=70", buf, sizeof(buf));
  static_assertRefusedWith(buf, "unknown query parameter; this endpoint takes vendor, product, min_risk_score, include_rejected, limit, offset", "/cve_triage?min_score=70");

  char* answer = static_mcpCall(R"({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"cve_lookup","arguments":{"cve_id":"CVE-2021-44228","ghsa":true}}})");
  TEST_ASSERT_NOT_NULL(strstr(answer, "Invalid params: unknown argument; this tool takes cve_id, include_ghsa"));
  free(answer);
  answer = static_mcpCall(R"({"jsonrpc":"2.0","id":2,"method":"tools/call","params":{"name":"cve_triage","arguments":{"min_score":70}}})");
  TEST_ASSERT_NOT_NULL(strstr(answer, "Invalid params: unknown argument; this tool takes vendor, product, min_risk_score, include_rejected, limit, offset"));
  free(answer);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CVELOOKUP_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CVETRIAGE_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CVELOOKUPGHSA_call_count);
}

