static int static_readSqlNumber(const char* path, const char* scope, const char* anchor)
{
  char* text = static_readDocsFile(path);
  const char* at = strstr(text, scope);
  TEST_ASSERT_NOT_NULL_MESSAGE(at, scope);
  at = strstr(at, anchor);
  TEST_ASSERT_NOT_NULL_MESSAGE(at, anchor);
  int number = 0;
  TEST_ASSERT_EQUAL_INT_MESSAGE(1, sscanf(at + strlen(anchor), "%d", &number), anchor);
  free(text);
  TEST_ASSERT_TRUE_MESSAGE(number > 0, anchor);
  return number;
}

