static void static_readSqlQuoted(const char* text, const char* scope, const char* anchor, char* out, size_t out_size)
{
  const char* at = strstr(text, scope);
  TEST_ASSERT_NOT_NULL_MESSAGE(at, scope);
  at = strstr(at + strlen(scope), anchor);
  TEST_ASSERT_NOT_NULL_MESSAGE(at, anchor);
  at += strlen(anchor);
  const char* end = strchr(at, '\'');
  TEST_ASSERT_NOT_NULL_MESSAGE(end, anchor);
  TEST_ASSERT_TRUE_MESSAGE((size_t)(end - at) < out_size, anchor);
  snprintf(out, out_size, "%.*s", (int)(end - at), at);
}

