  snprintf(phrase, sizeof(phrase), "names endoflife.date, under the %s license,", license);
  TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countOccurrences(api_text, phrase), phrase);
  snprintf(phrase, sizeof(phrase), "| [endoflife.date](https://endoflife.date/) | [%s](", license);
