void test_docs_repeated_name_messages_are_the_server_messages(void)
{
  char buf[RESP_BUF];
  char query_message[256];
  char body_message[256];
  static_restGet("/cve_lookup/CVE-2021-44228?include_ghsa=true&include_ghsa=true", buf, sizeof(buf));
  static_errorMessageOf(buf, query_message, sizeof(query_message));
  g_stub_api_key_state = DB_API_KEY_ACTIVE;
  static_CVELOOKUPBULKPostBody(R"({"cve_ids":["CVE-2021-44228"],"cve_ids":["CVE-2022-1"]})", buf, sizeof(buf));
  static_errorMessageOf(buf, body_message, sizeof(body_message));
  char items_message[256];
  static_postPackageCheckBulk(R"({"items":[],"items":[]})", buf, sizeof(buf));
  static_errorMessageOf(buf, items_message, sizeof(items_message));
  char vendor_key_edit_message[256];
  TEST_ASSERT_EQUAL_INT(400, static_watchlistRestAnswer("/vendor_key_edit", R"({"action":"apply","action":"status"})", true, vendor_key_edit_message, sizeof(vendor_key_edit_message)));

  char* api_text = static_readDocsFile(DOCS_API_PATH);
  bool has_query_copy = false;
  bool has_body_copy  = false;
  bool has_items_copy = false;
  bool has_vendor_key_edit_copy = false;
  for (const char* found = strstr(api_text, "appears more than once"); found; found = strstr(found + 1, "appears more than once"))
  {
    const char* open = found;
    while (open > api_text && open[-1] != '"' && open[-1] != '\n')
      open--;
    TEST_ASSERT_TRUE_MESSAGE(open > api_text && open[-1] == '"', "unquoted copy");
    const char* close = strchr(found, '"');
    TEST_ASSERT_NOT_NULL(close);
    size_t copy_len = (size_t)(close - open);
    bool is_query = strlen(query_message) == copy_len && memcmp(open, query_message, copy_len) == 0;
    bool is_body  = strlen(body_message)  == copy_len && memcmp(open, body_message,  copy_len) == 0;
    bool is_items = strlen(items_message) == copy_len && memcmp(open, items_message, copy_len) == 0;
    bool is_vendor_key_edit = strlen(vendor_key_edit_message) == copy_len && memcmp(open, vendor_key_edit_message, copy_len) == 0;
    TEST_ASSERT_TRUE_MESSAGE(is_query || is_body || is_items || is_vendor_key_edit, "a docs copy is no server message");
    has_query_copy = has_query_copy || is_query;
    has_body_copy  = has_body_copy  || is_body;
    has_items_copy = has_items_copy || is_items;
    has_vendor_key_edit_copy = has_vendor_key_edit_copy || is_vendor_key_edit;
  }
  TEST_ASSERT_TRUE(has_query_copy);
  TEST_ASSERT_TRUE(has_body_copy);
  TEST_ASSERT_TRUE(has_items_copy);
  TEST_ASSERT_TRUE(has_vendor_key_edit_copy);
  free(api_text);
}


