void test_webhook_nowpayments_bad_signature_shape_never_reaches_the_canonicalizer(void)
{
  billing_setNowPaymentsSecret(NP_TEST_SECRET);
  char signature[BILLING_NOWPAYMENTS_SIGNATURE_LEN + 1];
  static_signNowPayments(NP_PAID_BODY, signature);
  char upper_signature[BILLING_NOWPAYMENTS_SIGNATURE_LEN + 1];
  for (size_t i = 0; i <= BILLING_NOWPAYMENTS_SIGNATURE_LEN; i++)
    upper_signature[i] = (char)toupper((unsigned char)signature[i]);
  char short_line[192];
  char upper_line[192];
  char other_header_line[192];
  snprintf(short_line, sizeof(short_line), "x-nowpayments-sig: %.127s\r\n", signature);
  snprintf(upper_line, sizeof(upper_line), "x-nowpayments-sig: %s\r\n", upper_signature);
  snprintf(other_header_line, sizeof(other_header_line), "X-Signature: %s\r\n", signature);
  const char* lines[] = { "", "x-nowpayments-sig: \r\n", short_line, upper_line, other_header_line };

  g_jsonCanonCallCount      = 0;
  g_stub_billing_call_count = 0;
  for (size_t i = 0; i < sizeof(lines) / sizeof(lines[0]); i++)
  {
    char buf[RESP_BUF];
    static_postNowPayments(lines[i], NP_PAID_BODY, strlen(NP_PAID_BODY), buf, sizeof(buf));
    static_assertInvalidSignature(buf);
  }

  static char pathological_body[BILLING_NOWPAYMENTS_BODY_MAX_BYTE_COUNT];
  memset(pathological_body, '[', sizeof(pathological_body));
  char buf[RESP_BUF];
  static_postNowPayments(short_line, pathological_body, sizeof(pathological_body), buf, sizeof(buf));
  static_assertInvalidSignature(buf);

  char long_line[192];
  snprintf(long_line, sizeof(long_line), "x-nowpayments-sig: %s0\r\n", signature);
  static_postNowPayments(long_line, NP_PAID_BODY, strlen(NP_PAID_BODY), buf, sizeof(buf));
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 400"), buf);
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "x-nowpayments-sig is too long"), buf);

  TEST_ASSERT_EQUAL_INT(0, g_jsonCanonCallCount);
  TEST_ASSERT_EQUAL_INT(0, g_stub_billing_call_count);
}

