static const ParityCall_t* static_parityCallFor(const char* tool)
{
  for (size_t i = 0; i < sizeof(PARITY_CALLS) / sizeof(PARITY_CALLS[0]); i++)
    if (strcmp(PARITY_CALLS[i].mp_tool, tool) == 0)
      return &PARITY_CALLS[i];
  return NULL;
}

static char* static_mcpArgumentsCall(const char* tool, const char* arguments)
{
  char body[1024];
  int written = snprintf(body, sizeof(body), R"({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"%s","arguments":%s}})", tool, arguments);
  TEST_ASSERT_TRUE_MESSAGE(written > 0 && (size_t)written < sizeof(body), tool);
  return static_mcpCall(body);
}

static char* static_mcpAnswerForParityCall(const ParityCall_t* call)
{
  const Endpoint_t* endpoint = endpoint_findByMcpName(call->mp_tool);
  TEST_ASSERT_NOT_NULL_MESSAGE(endpoint, call->mp_tool);
  if (!endpoint->m_readsCreditBudget)
    return static_mcpArgumentsCall(call->mp_tool, call->mp_mcpArguments);

  static char buf[RESP_BUF];
  char* copy = strdup(static_mcpCallThroughRequestHandle(call->m_needsApiKey ? PARITY_KEY_HEADER : "", call->mp_tool, call->mp_mcpArguments, NULL, buf, sizeof(buf)));
  TEST_ASSERT_NOT_NULL(copy);
  return copy;
}

static int static_restStatusOf(const char* buf)
{
  int code = 0;
  if (sscanf(buf, "HTTP/1.1 %d", &code) != 1)
    return 0;
  return code;
}

void test_only_a_request_that_calls_an_upstream_service_enters(void)
{
  static_setParityStubsOk();
  static_useEveryUpstreamThread();

  char buf[RESP_BUF];
  char req[2048];
  for (size_t i = 0; i < sizeof(PARITY_CALLS) / sizeof(PARITY_CALLS[0]); i++)
  {
    const ParityCall_t* call = &PARITY_CALLS[i];
    bool will_call_upstream = strcmp(call->mp_tool, "password_check") == 0 || strcmp(call->mp_tool, "dns_lookup") == 0 ||
                              strcmp(call->mp_tool, "dns_takeover_check") == 0 || strcmp(call->mp_tool, "email_auth_check") == 0 ||
                              strcmp(call->mp_tool, "ip_lookup") == 0 || strcmp(call->mp_tool, "ssl_check") == 0 ||
                              strcmp(call->mp_tool, "whois_lookup") == 0 || strcmp(call->mp_tool, "wayback_lookup") == 0 ||
                              strcmp(call->mp_tool, "cert_search") == 0 || strcmp(call->mp_tool, "subdomain_enum") == 0 ||
                              strcmp(call->mp_tool, "email_address_check") == 0 || strcmp(call->mp_tool, "headers_check") == 0;

    static_callRequestHandle(call->mp_restRequest, buf, sizeof(buf));
    if (will_call_upstream)
      TEST_ASSERT_EQUAL_INT_MESSAGE(503, static_restStatusOf(buf), call->mp_tool);
    else
      TEST_ASSERT_NOT_EQUAL_INT_MESSAGE(503, static_restStatusOf(buf), call->mp_tool);

    int written = snprintf(req, sizeof(req), "POST /mcp HTTP/1.1\r\nContent-Type: application/json\r\n\r\n"
                           R"({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"%s","arguments":%s}})",
                           call->mp_tool, call->mp_mcpArguments);
    TEST_ASSERT_TRUE_MESSAGE(written > 0 && (size_t)written < sizeof(req), call->mp_tool);
    static_callRequestHandle(req, buf, sizeof(buf));
    if (will_call_upstream)
      TEST_ASSERT_EQUAL_INT_MESSAGE(503, static_restStatusOf(buf), call->mp_tool);
    else
      TEST_ASSERT_NOT_EQUAL_INT_MESSAGE(503, static_restStatusOf(buf), call->mp_tool);
  }
  TEST_ASSERT_EQUAL_INT(2, g_stub_CVELOOKUPGHSA_call_count);
  TEST_ASSERT_EQUAL_INT(2, g_stub_CVEEXPLOIT_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_PASSWORDCHECK_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_DNSLOOKUP_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_DNSTAKEOVERCHECK_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_EMAILAUTHCHECK_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_IPLOOKUP_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_PTR_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_TLSPROBE_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CACHE_get_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_RDAP_find_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_QUOTA_reserve_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_RDAP_lookup_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_WAYBACK_lookup_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CERTSPOTTER_lookup_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CERTSPOTTER_subtree_lookup_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_SUBDOMAIN_lookup_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_HEADER_FETCH_call_count);
  TEST_ASSERT_FALSE(upstream_tryEnter());
}

static void static_writeRouterDispatch(int client_fd, const void* context)
{
  const char* request = (const char*)context;
  char method[8];
  char target[256];
  TEST_ASSERT_EQUAL_INT_MESSAGE(2, sscanf(request, "%7s %255s", method, target), request);
  char* query = strchr(target, '?');
  if (query != NULL)
    *query++ = '\0';
  const char* body = strstr(request, "\r\n\r\n");
  TEST_ASSERT_NOT_NULL_MESSAGE(body, request);
  RouterParsedRequest_t parsed = { method, target, query != NULL ? query : "", body + 4, strlen(body + 4), NULL, NULL, NULL, 0 };
  const char* path_segment = NULL;
  const Endpoint_t* endpoint = endpoint_findByHttpPath(target, &path_segment);
  TEST_ASSERT_NOT_NULL_MESSAGE(endpoint, request);
  router_dispatch(&parsed, endpoint, path_segment, client_fd, g_conn, &TEST_FULL_CHARGE);
}

static void static_maskCheckedAt(char* text)
{
  char* member = strstr(text, R"("checked_at":")");
  if (member == NULL)
    return;
  char* value = member + strlen(R"("checked_at":")");
  for (size_t i = 0; i < TLSPROBE_TIME_TEXT_SIZE - 1 && value[i] != '\0' && value[i] != '"'; i++)
    value[i] = 'X';
}

static void static_maskManageUrlLink(char* text)
{
  for (char* at = strstr(text, "#l="); at != NULL; at = strstr(at + 3, "#l="))
  {
    char* link = at + 3;
    for (size_t i = 0; i < KEYVAULT_VENDOR_KEY_LINK_LEN && link[i] != '\0' && link[i] != '"'; i++)
      link[i] = 'X';
  }
}

static void static_assertMcpTextIs(const char* answer, const char* buf, const char* label)
{
  const char* head_end = strstr(buf, "\r\n\r\n");
  TEST_ASSERT_NOT_NULL_MESSAGE(head_end, label);
  char body[RESP_BUF];
  int written = snprintf(body, sizeof(body), "%s", head_end + 4);
  TEST_ASSERT_TRUE_MESSAGE(written >= 0 && (size_t)written < sizeof(body), label);
  char decoded[RESP_BUF];
  static_mcpTextOf(answer, decoded, sizeof(decoded), label);
  static_maskCheckedAt(body);
  static_maskCheckedAt(decoded);
  static_maskManageUrlLink(body);
  static_maskManageUrlLink(decoded);
  TEST_ASSERT_EQUAL_STRING_MESSAGE(body, decoded, label);
}

