static ListParams_t static_takeListParams(void)
{
  ListParams_t taken = { g_stub_CVESEARCH_last_params, g_stub_CVELEADING_last_params, g_stub_CVETRIAGE_last_params, g_stub_CPESEARCH_last_params,
                         g_stub_PACKAGECHECK_last_params, g_stub_CVEPRODUCTS_last_params, g_stub_PACKAGECHECKBULK_last_item_count,
                         { g_stub_PACKAGECHECKBULK_last_items[0], g_stub_PACKAGECHECKBULK_last_items[1] } };
  g_stub_PACKAGECHECKBULK_last_item_count = 0;
  memset(g_stub_PACKAGECHECKBULK_last_items, 0, 2 * sizeof(g_stub_PACKAGECHECKBULK_last_items[0]));
  memset(&g_stub_CVESEARCH_last_params, 0, sizeof(g_stub_CVESEARCH_last_params));
  memset(&g_stub_CVELEADING_last_params, 0, sizeof(g_stub_CVELEADING_last_params));
  memset(&g_stub_CVETRIAGE_last_params, 0, sizeof(g_stub_CVETRIAGE_last_params));
  memset(&g_stub_CPESEARCH_last_params, 0, sizeof(g_stub_CPESEARCH_last_params));
  memset(&g_stub_PACKAGECHECK_last_params, 0, sizeof(g_stub_PACKAGECHECK_last_params));
  memset(&g_stub_CVEPRODUCTS_last_params, 0, sizeof(g_stub_CVEPRODUCTS_last_params));
  return taken;
}

static void static_assertSameListParams(const char* tool, const ListParams_t* rest, const ListParams_t* mcp)
{
  if (strcmp(tool, "cve_search") == 0)
  {
    const CVESEARCHParams_t* a = &rest->m_search;
    const CVESEARCHParams_t* b = &mcp->m_search;
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_vendor, b->ma_vendor, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_product, b->ma_product, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_severity, b->ma_severity, tool);
    TEST_ASSERT_TRUE_MESSAGE(a->m_minCvss == b->m_minCvss, tool);
    TEST_ASSERT_TRUE_MESSAGE(a->m_minEpss == b->m_minEpss, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_kevFilter, b->m_kevFilter, tool);
    TEST_ASSERT_TRUE_MESSAGE(a->m_knownRansomware == b->m_knownRansomware, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_cweId, b->ma_cweId, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_publishedAfter, b->ma_publishedAfter, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_publishedBefore, b->ma_publishedBefore, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_sort, b->ma_sort, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_limit, b->m_limit, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_offset, b->m_offset, tool);
  }
  else if (strcmp(tool, "cve_leading") == 0)
  {
    const CVELEADINGParams_t* a = &rest->m_leading;
    const CVELEADINGParams_t* b = &mcp->m_leading;
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_vendor, b->ma_vendor, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_product, b->ma_product, tool);
    TEST_ASSERT_TRUE_MESSAGE(a->m_minEpss == b->m_minEpss, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_kevFilter, b->m_kevFilter, tool);
    TEST_ASSERT_TRUE_MESSAGE(a->m_knownRansomware == b->m_knownRansomware, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_limit, b->m_limit, tool);
  }
  else if (strcmp(tool, "cve_triage") == 0)
  {
    const CVETRIAGEParams_t* a = &rest->m_triage;
    const CVETRIAGEParams_t* b = &mcp->m_triage;
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_vendor, b->ma_vendor, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_product, b->ma_product, tool);
    TEST_ASSERT_TRUE_MESSAGE(a->m_minRiskScore == b->m_minRiskScore, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_limit, b->m_limit, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_offset, b->m_offset, tool);
  }
  else if (strcmp(tool, "cpe_search") == 0)
  {
    const CPESEARCHParams_t* a = &rest->m_cpeSearch;
    const CPESEARCHParams_t* b = &mcp->m_cpeSearch;
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_search, b->ma_search, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_limit, b->m_limit, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_offset, b->m_offset, tool);
  }
  else if (strcmp(tool, "package_check") == 0)
  {
    const PACKAGECHECKParams_t* a = &rest->m_packageCheck;
    const PACKAGECHECKParams_t* b = &mcp->m_packageCheck;
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_ecosystem, b->ma_ecosystem, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_packageName, b->ma_packageName, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_version, b->ma_version, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_limit, b->m_limit, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_offset, b->m_offset, tool);
  }
  else if (strcmp(tool, "package_check_bulk") == 0)
  {
    TEST_ASSERT_EQUAL_INT_MESSAGE(2, rest->m_packageItemCount, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(rest->m_packageItemCount, mcp->m_packageItemCount, tool);
    for (int k = 0; k < 2; k++)
    {
      TEST_ASSERT_EQUAL_STRING_MESSAGE(rest->ma_packageItems[k].ma_ecosystem, mcp->ma_packageItems[k].ma_ecosystem, tool);
      TEST_ASSERT_EQUAL_STRING_MESSAGE(rest->ma_packageItems[k].ma_packageName, mcp->ma_packageItems[k].ma_packageName, tool);
      TEST_ASSERT_EQUAL_STRING_MESSAGE(rest->ma_packageItems[k].ma_version, mcp->ma_packageItems[k].ma_version, tool);
    }
    TEST_ASSERT_EQUAL_STRING_MESSAGE("@scope/x", rest->ma_packageItems[1].ma_packageName, tool);
  }
  else if (strcmp(tool, "cve_products") == 0)
  {
    const CVEPRODUCTSParams_t* a = &rest->m_cveProducts;
    const CVEPRODUCTSParams_t* b = &mcp->m_cveProducts;
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_cveId, b->ma_cveId, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_vendor, b->ma_vendor, tool);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(a->ma_product, b->ma_product, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_limit, b->m_limit, tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(a->m_offset, b->m_offset, tool);
  }
}

void test_rest_and_mcp_send_one_success_body(void)
{
  static_setParityStubsOk();
  char buf[RESP_BUF];
  int checked = 0;
  for (int i = 0; i < endpoint_count; i++)
  {
    const Endpoint_t* endpoint = &endpoints[i];
    if (endpoint->mp_mcpToolName == NULL)
      continue;
    const ParityCall_t* call = static_parityCallFor(endpoint->mp_mcpToolName);
    TEST_ASSERT_NOT_NULL_MESSAGE(call, endpoint->mp_mcpToolName);

    g_stub_CVEEXPLOIT_last_conn = NULL;
    static_callRequestHandle(call->mp_restRequest, buf, sizeof(buf));
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), call->mp_tool);
    TEST_ASSERT_EQUAL_INT_MESSAGE(200, static_restStatusOf(buf), call->mp_tool);
    ListParams_t rest_params = static_takeListParams();
    PGconn* rest_exploit_conn = g_stub_CVEEXPLOIT_last_conn;

    g_stub_CVEEXPLOIT_last_conn = NULL;
    char* answer = static_mcpAnswerForParityCall(call);
    static_assertMcpTextIs(answer, buf, call->mp_tool);
    free(answer);
    ListParams_t mcp_params = static_takeListParams();
    static_assertSameListParams(call->mp_tool, &rest_params, &mcp_params);
    if (strcmp(call->mp_tool, "cve_exploit") == 0)
    {
      TEST_ASSERT_TRUE_MESSAGE(rest_exploit_conn == g_conn, "REST cve_exploit_fetch got another connection");
      TEST_ASSERT_TRUE_MESSAGE(g_stub_CVEEXPLOIT_last_conn == g_conn, "MCP cve_exploit_fetch got another connection");
    }
    checked++;
  }
  TEST_ASSERT_EQUAL_INT(37, checked);
  TEST_ASSERT_EQUAL_INT((int)(sizeof(PARITY_CALLS) / sizeof(PARITY_CALLS[0])), checked);
}

void test_rest_and_mcp_charge_one_price_for_every_accepted_parity_call(void)
{
  static_setParityStubsOk();
  int checked = 0;
  for (size_t i = 0; i < sizeof(PARITY_CALLS) / sizeof(PARITY_CALLS[0]); i++)
  {
    const ParityCall_t* call = &PARITY_CALLS[i];
    char method[8];
    char target[512];
    TEST_ASSERT_EQUAL_INT_MESSAGE(2, sscanf(call->mp_restRequest, "%7s %511s", method, target), call->mp_tool);
    const char* body = strstr(call->mp_restRequest, "\r\n\r\n");
    TEST_ASSERT_NOT_NULL_MESSAGE(body, call->mp_tool);
    unsigned int rest_price = static_costForRequest(method, target, body + 4);
    unsigned int mcp_price  = static_costForMcpTool(call->mp_tool, call->mp_mcpArguments);
    TEST_ASSERT_EQUAL_UINT_MESSAGE(rest_price, mcp_price, call->mp_tool);
    checked++;
  }
  TEST_ASSERT_EQUAL_INT(37, checked);
}

