void test_docs_mcp_not_found_texts_are_the_server_texts(void)
{
  char* docs = static_readDocsFile(DOCS_MCP_PATH);
  const char* row_prefix = "\n| CVE not found | `";
  const char* row = strstr(docs, row_prefix);
  TEST_ASSERT_NOT_NULL_MESSAGE(row, row_prefix);
  const char* row_end = strchr(row + strlen(row_prefix), '`');
  const char* result  = strstr(row, R"("result":)");
  TEST_ASSERT_TRUE(row_end != NULL && result != NULL && result < row_end);
  const char* is_error = strstr(result, R"("isError":true)");
  TEST_ASSERT_TRUE(is_error != NULL && is_error < row_end);
  size_t documented_len = (size_t)(is_error + strlen(R"("isError":true)") - result);
  char documented[256];
  TEST_ASSERT_TRUE(documented_len < sizeof(documented));
  memcpy(documented, result, documented_len);
  documented[documented_len] = '\0';
  char* answer = static_mcpToolCall("cve_lookup", "cve_id", R"("CVE-1999-99999")");
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(answer, documented), documented);
  free(answer);

  const Endpoint_t* kev = endpoint_findByMcpName("kev_lookup");
  TEST_ASSERT_NOT_NULL(kev);
  char sentence[128];
  int written = snprintf(sentence, sizeof(sentence), "Returns `isError:true` \"%s\" when", kev->mp_notFoundMessage);
  TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(sentence));
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(docs, sentence), sentence);
  free(docs);
}

static bool static_nextListedSpelling(const char** cursor, char* out, size_t out_size)
{
  const char* scan = *cursor;
  while (*scan != '\0' && *scan != '`' && *scan != '.')
    scan++;
  if (*scan != '`')
    return false;

  const char* close = strchr(scan + 1, '`');
  TEST_ASSERT_NOT_NULL(close);
  size_t len = (size_t)(close - (scan + 1));
  TEST_ASSERT_TRUE(len > 0 && len < out_size);
  memcpy(out, scan + 1, len);
  out[len] = '\0';
  *cursor = close + 1;
  return true;
}

void test_docs_number_and_cwe_id_refusals_match_the_server(void)
{
  g_stub_CVESEARCH_status = DB_OK;
  g_stub_api_key_state    = DB_API_KEY_ACTIVE;
  char buf[RESP_BUF];
  char min_cvss_message[256];
  static_restGet("/cve_search?min_cvss=11", buf, sizeof(buf));
  static_errorMessageOf(buf, min_cvss_message, sizeof(min_cvss_message));
  char cwe_id_message[256];
  static_restGet("/cve_search?cwe_id=79", buf, sizeof(buf));
  static_errorMessageOf(buf, cwe_id_message, sizeof(cwe_id_message));

  char* api_text = static_readDocsFile(DOCS_API_PATH);
  const char* rest_anchor = "are refused with 400: ";
  const char* cursor      = strstr(api_text, rest_anchor);
  TEST_ASSERT_NOT_NULL_MESSAGE(cursor, rest_anchor);
  cursor += strlen(rest_anchor);
  int  listed = 0;
  char spelling[32];
  while (static_nextListedSpelling(&cursor, spelling, sizeof(spelling)))
  {
    char path[64];
    int  written = snprintf(path, sizeof(path), "/cve_search?min_cvss=%s", spelling);
    TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(path));
    static_restGet(path, buf, sizeof(buf));
    static_assertRefusedWith(buf, min_cvss_message, path);
    listed++;
  }
  TEST_ASSERT_TRUE_MESSAGE(listed > 0, rest_anchor);
  TEST_ASSERT_EQUAL_INT_MESSAGE('.', *cursor, rest_anchor);
  static_assertEveryMention(api_text, "cwe_id must be", cwe_id_message, '"');
  free(api_text);

  char* mcp_text = static_readDocsFile(DOCS_MCP_PATH);
  const char* mcp_anchor = "are tool errors: ";
  cursor = strstr(mcp_text, mcp_anchor);
  TEST_ASSERT_NOT_NULL_MESSAGE(cursor, mcp_anchor);
  cursor += strlen(mcp_anchor);
  char needle[320];
  int  written = snprintf(needle, sizeof(needle), R"("text":"%s"}],"isError":true)", min_cvss_message);
  TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(needle));
  listed = 0;
  while (static_nextListedSpelling(&cursor, spelling, sizeof(spelling)))
  {
    char body[256];
    written = snprintf(body, sizeof(body), R"({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"cve_search","arguments":{"min_cvss":%s}}})", spelling);
    TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(body));
    char* answer = static_mcpCall(body);
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(answer, needle), body);
    free(answer);
    listed++;
  }
  TEST_ASSERT_TRUE_MESSAGE(listed > 0, mcp_anchor);
  TEST_ASSERT_EQUAL_INT_MESSAGE('.', *cursor, mcp_anchor);
  static_assertEveryMention(mcp_text, "cwe_id must be", cwe_id_message, '"');
  free(mcp_text);
}

static void static_assertEveryRepeatMention(const char* text, const char* const messages[3], char closing_mark)
{
  static const char* const names[] = { "cve_ids[", "hashes[", "items[" };
  int         mention_counts[]     = { 0, 0, 0 };
  const char* anchor               = "] repeats";
  for (const char* found = strstr(text, anchor); found; found = strstr(found + 1, anchor))
  {
    const char* digits_start = found;
    while (digits_start > text && digits_start[-1] >= '0' && digits_start[-1] <= '9')
      digits_start--;
    int kind = -1;
    for (int k = 0; k < 3; k++)
    {
      size_t name_len = strlen(names[k]);
      if ((size_t)(digits_start - text) >= name_len && strncmp(digits_start - name_len, names[k], name_len) == 0)
        kind = k;
    }
    TEST_ASSERT_TRUE_MESSAGE(kind >= 0, digits_start);
    const char* start       = digits_start - strlen(names[kind]);
    size_t      message_len = strlen(messages[kind]);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, strncmp(start, messages[kind], message_len), start);
    TEST_ASSERT_EQUAL_INT_MESSAGE(closing_mark, start[message_len], start);
    mention_counts[kind]++;
  }
  TEST_ASSERT_TRUE_MESSAGE(mention_counts[0] > 0, names[0]);
  TEST_ASSERT_TRUE_MESSAGE(mention_counts[1] > 0, names[1]);
  TEST_ASSERT_TRUE_MESSAGE(mention_counts[2] > 0, names[2]);
}

