void test_watchlist_events_costs_one_credit_and_refuses_kev_and_exploit(void)
{
  g_stub_WATCHLISTEVENTS_status = DB_OK;
  TEST_ASSERT_EQUAL_UINT(1, static_costForPath("/watchlist_events"));
  TEST_ASSERT_EQUAL_UINT(1, static_costForPath("/watchlist_events?kev=true"));
  TEST_ASSERT_EQUAL_UINT(1, static_costForPath("/watchlist_events?exploit=true"));
  TEST_ASSERT_EQUAL_UINT(1, static_costForPath("/watchlist_events?limit=5&cursor=41"));
  TEST_ASSERT_EQUAL_UINT(1, static_costForRequest("POST", "/watchlist_edit", "{}"));
  TEST_ASSERT_EQUAL_UINT(1, static_costForRequest("POST", "/watchlist_edit", R"({"action":"add","endpoint":"cve_lookup","cve_id":"CVE-2021-44228"})"));
  TEST_ASSERT_EQUAL_UINT(1, static_costForRequest("POST", "/watchlist_edit", "not json"));
  TEST_ASSERT_EQUAL_UINT(1, static_costForRequest("GET", "/watchlist_edit", ""));
  TEST_ASSERT_EQUAL_UINT(1, static_costForMcpTool("watchlist_events", "{}"));
  TEST_ASSERT_EQUAL_UINT(1, static_costForMcpTool("watchlist_events", R"({"kev":true})"));
  TEST_ASSERT_EQUAL_UINT(1, static_costForMcpTool("watchlist_events", R"({"kev":true,"exploit":true})"));
  TEST_ASSERT_EQUAL_UINT(1, static_costForMcpTool("watchlist_edit", R"({"action":"add"})"));

  g_stub_WATCHLISTEVENTS_call_count = 0;
  char message[ENDPOINT_MESSAGE_BUF_SIZE];
  TEST_ASSERT_EQUAL_INT(400, static_watchlistRestAnswer("/watchlist_events?kev=true", NULL, true, message, sizeof(message)));
  TEST_ASSERT_EQUAL_STRING("unknown query parameter; this endpoint takes limit, cursor, repeat", message);
  TEST_ASSERT_EQUAL_INT(400, static_watchlistRestAnswer("/watchlist_events?exploit=true", NULL, true, message, sizeof(message)));
  TEST_ASSERT_EQUAL_STRING("unknown query parameter; this endpoint takes limit, cursor, repeat", message);
  TEST_ASSERT_EQUAL_INT(200, static_watchlistRestAnswer("/watchlist_events?limit=5", NULL, true, message, sizeof(message)));
  TEST_ASSERT_EQUAL_INT(1, g_stub_WATCHLISTEVENTS_call_count);

  static char buf[RESP_BUF];
  const char* answer = static_mcpCallThroughRequestHandle(PARITY_KEY_HEADER, "watchlist_events", R"({"kev":true})", NULL, buf, sizeof(buf));
  TEST_ASSERT_NOT_NULL(strstr(answer, R"("code":-32602)"));
  TEST_ASSERT_NOT_NULL(strstr(answer, "Invalid params: unknown argument; this tool takes limit, cursor, repeat"));
  TEST_ASSERT_EQUAL_INT(1, g_stub_WATCHLISTEVENTS_call_count);
}

