#define VENDORKEY_SHODAN_KEY     "ShodanKey0123456789abcdefABCDEF00"
#define VENDORKEY_ABUSEIPDB_KEY  "abuse-key_9876~zyx"


static void static_vendorKeyParams(VENDORKEYEDITParams_t* params, const char* action, const char* link, const char* shodan_key, const char* abuseipdb_key)
{
  memset(params, 0, sizeof(*params));
  snprintf(params->ma_action, sizeof(params->ma_action), "%s", action);
  snprintf(params->ma_link, sizeof(params->ma_link), "%s", link);
  snprintf(params->ma_shodanKey, sizeof(params->ma_shodanKey), "%s", shodan_key);
  snprintf(params->ma_abuseIpDbKey, sizeof(params->ma_abuseIpDbKey), "%s", abuseipdb_key);
}

static EndpointRunStatus_t static_vendorKeyRun(VENDORKEYEDITParams_t* edit_params, RequestTier_t tier, char* body_out, size_t body_size, const char** message_out)
{
  RequestCreditBudget_t credit_budget;
  memset(&credit_budget, 0, sizeof(credit_budget));
  credit_budget.m_tier = tier;
  snprintf(credit_budget.ma_budgetHash, sizeof(credit_budget.ma_budgetHash), "%s", "b0b0b0");
  EndpointAnyParams_t params;
  memset(&params, 0, sizeof(params));
  params.m_vendorKeyEdit                 = *edit_params;
  params.m_vendorKeyEdit.mp_creditBudget = &credit_budget;
  JsonBuf_t* json_buf = jsonbuf_create(256, JSONBUF_DEFAULT_CEILING);
  TEST_ASSERT_NOT_NULL(json_buf);
  *message_out = NULL;
  EndpointRunStatus_t run_status = endpoint_VENDORKEYEDITRun(FAKE_CONN, &params, json_buf, message_out);
  char* body = jsonbuf_finish(json_buf);
  jsonbuf_destroy(json_buf);
  snprintf(body_out, body_size, "%s", body != NULL ? body : "");
  free(body);
  *edit_params = params.m_vendorKeyEdit;
  return run_status;
}

#define VENDORKEY_LINK_INVALID_MESSAGE "link_invalid: the link is not valid or was used already; ask /privacy_my_data for a new one"
#define VENDORKEY_LINK_EXPIRED_MESSAGE "link_expired: the link has ended; ask /privacy_my_data for a new one"

void test_vendor_key_edit_refusals_are_fixed_texts_before_any_call(void)
{
  static const char link[] = VENDORKEY_TEST_LINK;

  enum { STUB_NONE, STUB_KEY_ID_0, STUB_INVALID, STUB_EXPIRED };
  const struct {
    const char* mp_name; const char* mp_action; const char* mp_link; RequestTier_t m_tier; int m_stub;
    const char* mp_shodanKey; bool m_isShodanDeleted; const char* mp_abuseIpDbKey; bool m_isAbuseIpDbDeleted; const char* mp_message;
    int m_editReads;
  } cases[] = {
    { "free api key",         "apply",  "",               REQUEST_TIER_FREE, STUB_NONE,     VENDORKEY_SHODAN_KEY, false, "", false,
      "pro_key_required: vendor keys need a Pro API key: https://api.contrastcyber.com/pricing", 0 },
    { "inactive api key",     "apply",  "",               REQUEST_TIER_PRO,  STUB_KEY_ID_0, VENDORKEY_SHODAN_KEY, false, "", false,
      "pro_key_required: vendor keys need a Pro API key: https://api.contrastcyber.com/pricing", 0 },
    { "expired link",        "status", link,            REQUEST_TIER_PRO,  STUB_EXPIRED,  "", false, "", false,
      VENDORKEY_LINK_EXPIRED_MESSAGE, 1 },
    { "expired link apply",  "apply",  link,            REQUEST_TIER_FREE, STUB_EXPIRED,  VENDORKEY_SHODAN_KEY, false, "", false,
      VENDORKEY_LINK_EXPIRED_MESSAGE, 1 },
    { "invalid link",        "apply",  link,            REQUEST_TIER_FREE, STUB_INVALID,  VENDORKEY_SHODAN_KEY, false, "", false,
      VENDORKEY_LINK_INVALID_MESSAGE, 1 },
    { "invalid link status", "status", link,            REQUEST_TIER_FREE, STUB_INVALID,  "", false, "", false,
      VENDORKEY_LINK_INVALID_MESSAGE, 1 },
    { "nothing",              "apply",  link,            REQUEST_TIER_FREE, STUB_NONE,     "", false, "", false,
      "nothing_to_change: send shodan_key, abuseipdb_key, shodan_delete or abuseipdb_delete", 1 },
    { "shodan both",          "apply",  link,            REQUEST_TIER_FREE, STUB_NONE,     VENDORKEY_SHODAN_KEY, true, "", false,
      "bad_request: one vendor takes a key or a delete, not both", 1 },
    { "abuseipdb both",       "apply",  "",               REQUEST_TIER_PRO,  STUB_NONE,     "", false, VENDORKEY_ABUSEIPDB_KEY, true,
      "bad_request: one vendor takes a key or a delete, not both", 0 },
    { "shodan format",        "apply",  link,            REQUEST_TIER_FREE, STUB_NONE,     "Shodan-Key", false, VENDORKEY_ABUSEIPDB_KEY, false,
      "vendor_key_format: a vendor key does not have the form its vendor uses", 1 },
    { "abuseipdb format",     "apply",  "",               REQUEST_TIER_PRO,  STUB_NONE,     VENDORKEY_SHODAN_KEY, false, "abuse key", false,
      "vendor_key_format: a vendor key does not have the form its vendor uses", 0 },
    { "status without link", "status", "",               REQUEST_TIER_PRO,  STUB_NONE,     "", false, "", false,
      "bad_request: status needs link, the part after #l= in a manage link", 0 },
  };
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    static_resetVendorKeyStubs();
    if (cases[i].m_stub == STUB_KEY_ID_0)
      g_stub_vendor_keys.m_apiKeyId = 0;
    else if (cases[i].m_stub == STUB_INVALID)
      g_stub_vendor_key_link.m_linkState = DB_VENDOR_KEY_LINK_INVALID;
    else if (cases[i].m_stub == STUB_EXPIRED)
      g_stub_vendor_key_link.m_linkState = DB_VENDOR_KEY_LINK_EXPIRED;
    VENDORKEYEDITParams_t edit_params;
    static_vendorKeyParams(&edit_params, cases[i].mp_action, cases[i].mp_link, cases[i].mp_shodanKey, cases[i].mp_abuseIpDbKey);
    edit_params.m_isShodanDeleted    = cases[i].m_isShodanDeleted;
    edit_params.m_isAbuseIpDbDeleted = cases[i].m_isAbuseIpDbDeleted;
    char body[512];
    const char* message = NULL;
    TEST_ASSERT_EQUAL_INT_MESSAGE(ENDPOINT_RUN_REFUSED, static_vendorKeyRun(&edit_params, cases[i].m_tier, body, sizeof(body), &message), cases[i].mp_name);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(cases[i].mp_message, message, cases[i].mp_name);
    TEST_ASSERT_EQUAL_STRING_MESSAGE("", body, cases[i].mp_name);
    TEST_ASSERT_EQUAL_INT_MESSAGE(cases[i].m_editReads, g_stub_vendor_key_link_read_call_count, cases[i].mp_name);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, g_stub_SHODAN_check_count, cases[i].mp_name);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, g_stub_ABUSEIPDB_check_count, cases[i].mp_name);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, g_stub_vendor_key_apply_call_count, cases[i].mp_name);
  }
}

void test_vendor_keys_script_has_a_text_for_each_typing_refusal(void)
{
  char* script = static_readDocsFile("web/static/js/vendor_keys.js");
  const struct { const char* mp_name; const char* mp_shodanKey; } cases[] = {
    { "wrong form", "Shodan-Key" },
    { "nothing",    ""           },
  };
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    static_resetVendorKeyStubs();
    VENDORKEYEDITParams_t edit_params;
    static_vendorKeyParams(&edit_params, "apply", VENDORKEY_TEST_LINK, cases[i].mp_shodanKey, "");
    char body[512];
    const char* message = NULL;
    TEST_ASSERT_EQUAL_INT_MESSAGE(ENDPOINT_RUN_REFUSED, static_vendorKeyRun(&edit_params, REQUEST_TIER_FREE, body, sizeof(body), &message), cases[i].mp_name);
    const char* colon = strchr(message, ':');
    TEST_ASSERT_NOT_NULL_MESSAGE(colon, message);
    char phrase[96];
    snprintf(phrase, sizeof(phrase), "    %.*s: '", (int)(colon - message), message);
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countOccurrences(script, phrase), phrase);
  }
  free(script);
}

void test_vendor_key_edit_link_apply_saves_both_and_spends(void)
{
  VENDORKEYEDITParams_t edit_params;
  static_vendorKeyParams(&edit_params, "apply", VENDORKEY_TEST_LINK, VENDORKEY_SHODAN_KEY, VENDORKEY_ABUSEIPDB_KEY);
  char body[512];
  const char* message = NULL;
  TEST_ASSERT_EQUAL_INT(ENDPOINT_RUN_OK, static_vendorKeyRun(&edit_params, REQUEST_TIER_FREE, body, sizeof(body), &message));
  TEST_ASSERT_EQUAL_STRING(R"({"shodan":{"result":"saved","configured":true},"abuseipdb":{"result":"saved","configured":true}})" "\n", body);
  TEST_ASSERT_EQUAL_INT(1, g_stub_SHODAN_check_count);
  TEST_ASSERT_EQUAL_size_t(strlen(VENDORKEY_SHODAN_KEY), g_stub_SHODAN_last_key_len);
  TEST_ASSERT_EQUAL_INT(1, g_stub_ABUSEIPDB_check_count);
  TEST_ASSERT_EQUAL_size_t(strlen(VENDORKEY_ABUSEIPDB_KEY), g_stub_ABUSEIPDB_last_key_len);
  TEST_ASSERT_EQUAL_STRING("127.0.0.1", g_stub_ABUSEIPDB_last_ip);
  TEST_ASSERT_EQUAL_INT(1, g_stub_vendor_key_apply_call_count);
  const DbVendorKeyChange_t* change = &g_stub_vendor_key_last_change;
  TEST_ASSERT_EQUAL_INT64(VENDORKEY_LINK_API_KEY_ID, change->m_apiKeyId);
  TEST_ASSERT_NOT_NULL(change->mp_linkHash);
  TEST_ASSERT_EQUAL_STRING(VENDORKEY_TEST_LINK_HASH, change->mp_linkHash);
  TEST_ASSERT_NULL(change->mp_keyFingerprint);
  TEST_ASSERT_TRUE(change->m_isLinkSpent);
  TEST_ASSERT_FALSE(change->m_isShodanDeleted);
  TEST_ASSERT_FALSE(change->m_isAbuseIpDbDeleted);
  TEST_ASSERT_NOT_NULL(change->mp_shodanSealedHex);
  TEST_ASSERT_NOT_NULL(change->mp_abuseIpDbSealedHex);
  char opened[KEYVAULT_VENDOR_KEY_MAX_LEN + 1];
  size_t opened_len = 0;
  TEST_ASSERT_TRUE(keyvault_tryOpen(VENDORKEY_LINK_API_KEY_ID, "shodan", change->mp_shodanSealedHex, opened, &opened_len));
  TEST_ASSERT_EQUAL_STRING(VENDORKEY_SHODAN_KEY, opened);
  TEST_ASSERT_TRUE(keyvault_tryOpen(VENDORKEY_LINK_API_KEY_ID, "abuseipdb", change->mp_abuseIpDbSealedHex, opened, &opened_len));
  TEST_ASSERT_EQUAL_STRING(VENDORKEY_ABUSEIPDB_KEY, opened);
  char zero[KEYVAULT_VENDOR_KEY_MAX_LEN + 1];
  memset(zero, 0, sizeof(zero));
  TEST_ASSERT_EQUAL_MEMORY(zero, edit_params.ma_shodanKey, sizeof(zero));
  TEST_ASSERT_EQUAL_MEMORY(zero, edit_params.ma_abuseIpDbKey, sizeof(zero));
}

void test_vendor_key_edit_partial_apply_saves_the_passing_vendor(void)
{
  static const char link[] = VENDORKEY_TEST_LINK;
  const struct { const char* mp_name; ShodanStatus_t m_shodan; AbuseIpDbStatus_t m_abuseIpDb; unsigned int m_retry; const char* mp_body; } cases[] = {
    { "abuseipdb rejected", SHODAN_OK, ABUSEIPDB_KEY_REJECTED, 0,
      R"({"shodan":{"result":"saved","configured":true},"abuseipdb":{"result":"rejected","configured":false}})" "\n" },
    { "shodan rate limited", SHODAN_RATE_LIMITED, ABUSEIPDB_OK, 17,
      R"({"shodan":{"result":"vendor_unavailable","configured":true,"retry_after_seconds":17},"abuseipdb":{"result":"saved","configured":true}})" "\n" },
    { "abuseipdb unavailable", SHODAN_OK, ABUSEIPDB_UNAVAILABLE, 0,
      R"({"shodan":{"result":"saved","configured":true},"abuseipdb":{"result":"vendor_unavailable","configured":false}})" "\n" },
    { "abuseipdb rate limited", SHODAN_OK, ABUSEIPDB_RATE_LIMITED, 23,
      R"({"shodan":{"result":"saved","configured":true},"abuseipdb":{"result":"vendor_unavailable","configured":false,"retry_after_seconds":23}})" "\n" },
  };
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    static_resetVendorKeyStubs();
    snprintf(g_stub_vendor_key_link.ma_shodanSealedHex, sizeof(g_stub_vendor_key_link.ma_shodanSealedHex), "%s", "01ab");
    g_stub_SHODAN_check_status           = cases[i].m_shodan;
    g_stub_ABUSEIPDB_status              = cases[i].m_abuseIpDb;
    g_stub_SHODAN_retry_after_seconds    = cases[i].m_shodan == SHODAN_RATE_LIMITED ? cases[i].m_retry : 0;
    g_stub_ABUSEIPDB_retry_after_seconds = cases[i].m_abuseIpDb == ABUSEIPDB_RATE_LIMITED ? cases[i].m_retry : 0;
    VENDORKEYEDITParams_t edit_params;
    static_vendorKeyParams(&edit_params, "apply", link, VENDORKEY_SHODAN_KEY, VENDORKEY_ABUSEIPDB_KEY);
    char body[512];
    const char* message = NULL;
    TEST_ASSERT_EQUAL_INT_MESSAGE(ENDPOINT_RUN_OK, static_vendorKeyRun(&edit_params, REQUEST_TIER_FREE, body, sizeof(body), &message), cases[i].mp_name);
    TEST_ASSERT_EQUAL_STRING_MESSAGE(cases[i].mp_body, body, cases[i].mp_name);
    bool is_shodan_saved    = cases[i].m_shodan == SHODAN_OK;
    bool is_abuseipdb_saved = cases[i].m_abuseIpDb == ABUSEIPDB_OK;
    TEST_ASSERT_EQUAL_INT_MESSAGE(is_shodan_saved || is_abuseipdb_saved ? 1 : 0, g_stub_vendor_key_apply_call_count, cases[i].mp_name);
    TEST_ASSERT_FALSE_MESSAGE(g_stub_vendor_key_last_change.m_isLinkSpent, cases[i].mp_name);
    TEST_ASSERT_EQUAL_MESSAGE(is_shodan_saved, g_stub_vendor_key_last_change.mp_shodanSealedHex != NULL, cases[i].mp_name);
    TEST_ASSERT_EQUAL_MESSAGE(is_abuseipdb_saved, g_stub_vendor_key_last_change.mp_abuseIpDbSealedHex != NULL, cases[i].mp_name);
  }
}

