void test_vendor_key_edit_status_reports_each_key(void)
{
  int64_t expires_at = (int64_t)time(NULL) + 600;
  static const char link[] = VENDORKEY_TEST_LINK;
  char shodan_sealed[KEYVAULT_SEALED_HEX_MAX_LEN + 1];
  char abuseipdb_sealed[KEYVAULT_SEALED_HEX_MAX_LEN + 1];
  TEST_ASSERT_TRUE(keyvault_trySeal(VENDORKEY_LINK_API_KEY_ID, "shodan", VENDORKEY_SHODAN_KEY, strlen(VENDORKEY_SHODAN_KEY), shodan_sealed));
  TEST_ASSERT_TRUE(keyvault_trySeal(VENDORKEY_LINK_API_KEY_ID, "abuseipdb", VENDORKEY_ABUSEIPDB_KEY, strlen(VENDORKEY_ABUSEIPDB_KEY), abuseipdb_sealed));
  const struct { const char* mp_name; bool m_hasShodan; ShodanStatus_t m_shodan; bool m_hasAbuseIpDb; AbuseIpDbStatus_t m_abuseIpDb; const char* mp_states; } cases[] = {
    { "both working",      true,  SHODAN_OK,           true,  ABUSEIPDB_OK,           R"({"shodan":{"state":"working"},"abuseipdb":{"state":"working"},)" },
    { "both rejected",     true,  SHODAN_KEY_REJECTED, true,  ABUSEIPDB_KEY_REJECTED, R"({"shodan":{"state":"rejected"},"abuseipdb":{"state":"rejected"},)" },
    { "both rate limited", true,  SHODAN_RATE_LIMITED, true,  ABUSEIPDB_RATE_LIMITED, R"({"shodan":{"state":"vendor_unavailable"},"abuseipdb":{"state":"vendor_unavailable"},)" },
    { "abuseipdb down",    false, SHODAN_OK,           true,  ABUSEIPDB_UNAVAILABLE,  R"({"shodan":{"state":"not_configured"},"abuseipdb":{"state":"vendor_unavailable"},)" },
    { "shodan only",       true,  SHODAN_OK,           false, ABUSEIPDB_OK,           R"({"shodan":{"state":"working"},"abuseipdb":{"state":"not_configured"},)" },
    { "none stored",       false, SHODAN_OK,           false, ABUSEIPDB_OK,           R"({"shodan":{"state":"not_configured"},"abuseipdb":{"state":"not_configured"},)" },
  };
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    static_resetVendorKeyStubs();
    g_stub_vendor_key_link.m_linkExpiresAt = expires_at;
    if (cases[i].m_hasShodan)
      snprintf(g_stub_vendor_key_link.ma_shodanSealedHex, sizeof(g_stub_vendor_key_link.ma_shodanSealedHex), "%s", shodan_sealed);
    if (cases[i].m_hasAbuseIpDb)
      snprintf(g_stub_vendor_key_link.ma_abuseIpDbSealedHex, sizeof(g_stub_vendor_key_link.ma_abuseIpDbSealedHex), "%s", abuseipdb_sealed);
    g_stub_SHODAN_check_status = cases[i].m_shodan;
    g_stub_ABUSEIPDB_status    = cases[i].m_abuseIpDb;
    VENDORKEYEDITParams_t edit_params;
    static_vendorKeyParams(&edit_params, "status", link, "", "");
    char body[512];
    const char* message = NULL;
    TEST_ASSERT_EQUAL_INT_MESSAGE(ENDPOINT_RUN_OK, static_vendorKeyRun(&edit_params, REQUEST_TIER_FREE, body, sizeof(body), &message), cases[i].mp_name);
    size_t states_len = strlen(cases[i].mp_states);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, strncmp(cases[i].mp_states, body, states_len), body);
    long long expires_in = -1;
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, sscanf(body + states_len, R"("expires_in_seconds":%lld})" "\n", &expires_in), body);
    TEST_ASSERT_TRUE_MESSAGE(expires_in >= 590 && expires_in <= 600, body);
    TEST_ASSERT_EQUAL_INT_MESSAGE(cases[i].m_hasShodan ? 1 : 0, g_stub_SHODAN_check_count, cases[i].mp_name);
    TEST_ASSERT_EQUAL_size_t_MESSAGE(cases[i].m_hasShodan ? strlen(VENDORKEY_SHODAN_KEY) : 0, g_stub_SHODAN_last_key_len, cases[i].mp_name);
    TEST_ASSERT_EQUAL_INT_MESSAGE(cases[i].m_hasAbuseIpDb ? 1 : 0, g_stub_ABUSEIPDB_check_count, cases[i].mp_name);
    TEST_ASSERT_EQUAL_size_t_MESSAGE(cases[i].m_hasAbuseIpDb ? strlen(VENDORKEY_ABUSEIPDB_KEY) : 0, g_stub_ABUSEIPDB_last_key_len, cases[i].mp_name);
    if (cases[i].m_hasAbuseIpDb)
      TEST_ASSERT_EQUAL_STRING_MESSAGE("127.0.0.1", g_stub_ABUSEIPDB_last_ip, cases[i].mp_name);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, g_stub_vendor_key_apply_call_count, cases[i].mp_name);
  }
}

