void test_vendor_keys_manage_url_helper(void)
{
  char manage_url[ENDPOINT_RUN_VENDOR_KEYS_MANAGE_URL_BUF_SIZE];
  TEST_ASSERT_EQUAL_size_t(sizeof("https://api.contrastcyber.com/vendor-keys#l=") + KEYVAULT_VENDOR_KEY_LINK_LEN, sizeof(manage_url));

  DbVendorKeys_t vendor_keys = g_stub_vendor_keys;
  vendor_keys.m_apiKeyId = 0;
  memset(manage_url, 'x', sizeof(manage_url));
  TEST_ASSERT_FALSE(endpoint_tryWriteVendorKeysManageUrl(FAKE_CONN, &vendor_keys, manage_url));
  TEST_ASSERT_EQUAL_STRING("", manage_url);
  TEST_ASSERT_EQUAL_INT(0, g_stub_vendor_key_link_open_call_count);

  const DbStatus_t failed[] = { DB_NOT_FOUND, DB_ERROR };
  for (size_t i = 0; i < 2; i++)
  {
    g_stub_vendor_key_link_open_db_status = failed[i];
    memset(manage_url, 'x', sizeof(manage_url));
    TEST_ASSERT_FALSE(endpoint_tryWriteVendorKeysManageUrl(FAKE_CONN, &g_stub_vendor_keys, manage_url));
    TEST_ASSERT_EQUAL_STRING("", manage_url);
  }

  g_stub_vendor_key_link_open_db_status = DB_OK;
  TEST_ASSERT_TRUE(endpoint_tryWriteVendorKeysManageUrl(FAKE_CONN, &g_stub_vendor_keys, manage_url));
  static const char prefix[] = "https://api.contrastcyber.com/vendor-keys#l=";
  TEST_ASSERT_EQUAL_INT(0, strncmp(prefix, manage_url, sizeof(prefix) - 1));
  TEST_ASSERT_EQUAL_size_t(sizeof(prefix) - 1 + KEYVAULT_VENDOR_KEY_LINK_LEN, strlen(manage_url));
  static_assertManageLink(manage_url + sizeof(prefix) - 1, manage_url);

  char second_url[ENDPOINT_RUN_VENDOR_KEYS_MANAGE_URL_BUF_SIZE];
  TEST_ASSERT_TRUE(endpoint_tryWriteVendorKeysManageUrl(FAKE_CONN, &g_stub_vendor_keys, second_url));
  static_assertManageLink(second_url + sizeof(prefix) - 1, second_url);
  TEST_ASSERT_TRUE(strcmp(manage_url, second_url) != 0);
}

