static EndpointRunStatus_t static_ipLookupRunAt(RequestTier_t tier, const char* ip_address, char* body_out, size_t body_size)
{
  RequestCreditBudget_t credit_budget;
  memset(&credit_budget, 0, sizeof(credit_budget));
  credit_budget.m_tier = tier;
  snprintf(credit_budget.ma_budgetHash, sizeof(credit_budget.ma_budgetHash), "%s", "b0b0b0");
  EndpointAnyParams_t params;
  memset(&params, 0, sizeof(params));
  params.m_ipLookup.mp_creditBudget = &credit_budget;
  snprintf(params.m_ipLookup.ma_ipAddress, sizeof(params.m_ipLookup.ma_ipAddress), "%s", ip_address);
  JsonBuf_t* json_buf = jsonbuf_create(256, JSONBUF_DEFAULT_CEILING);
  TEST_ASSERT_NOT_NULL(json_buf);
  const char* message = NULL;
  EndpointRunStatus_t run_status = endpoint_IPLOOKUPRun(FAKE_CONN, &params, json_buf, &message);
  char* body = jsonbuf_finish(json_buf);
  jsonbuf_destroy(json_buf);
  snprintf(body_out, body_size, "%s", body != NULL ? body : "");
  free(body);
  return run_status;
}

static EndpointRunStatus_t static_ipLookupRun(RequestTier_t tier, char* body_out, size_t body_size)
{
  return static_ipLookupRunAt(tier, "8.8.8.8", body_out, body_size);
}

