void test_ip_lookup_pro_slots_follow_the_stored_keys_and_the_vendors(void)
{
  enum { NONE, OWN, OTHER };
  static const char FILLED_IE[]  = R"({"available":true,"source":"shodan","ports":[22,8443],"vulns":["CVE-2014-0160","CVE-2021-44228"],"vulns_truncated":false,"hostnames":["h\"1.example.net"],"tags":["vpn"],"last_update":"2026-10-30T11:22:33.123456"})";
  static const char EMPTY_IE[]   = R"({"available":true,"source":"shodan","ports":[],"vulns":[],"vulns_truncated":false,"hostnames":[],"tags":[],"last_update":null})";
  static const char FILLED_REP[] = R"({"available":true,"source":"abuseipdb","abuse_confidence_score":87,"total_reports":41,"distinct_reporter_count":9,"last_reported_at":"2026-11-01T08:00:00+00:00","is_whitelisted":false,"usage_type":"Data Center/Web Hosting/Transit"})";
  static const char MISSING[]    = R"({"available":false,"reason":"vendor_key_missing","action_url":"https://api.contrastcyber.com/privacy_my_data","action_tool":"privacy_my_data"})";
  static const char REJECTED[]   = R"({"available":false,"reason":"vendor_key_rejected","action_url":"https://api.contrastcyber.com/privacy_my_data","action_tool":"privacy_my_data"})";
  static const char DB_ERR[]     = R"({"available":false,"reason":"database_error"})";
  static const char UNAVAIL[]    = R"({"available":false,"reason":"vendor_unavailable"})";
  const struct {
    const char*       mp_name;
    int               m_shodanKey;
    ShodanStatus_t    m_shodan;
    unsigned int      m_shodanRetry;
    int               m_abuseIpDbKey;
    AbuseIpDbStatus_t m_abuseIpDb;
    unsigned int      m_abuseIpDbRetry;
    const char*       mp_reputation;
    const char*       mp_internetExposure;
    int               m_shodanCalls;
    int               m_abuseIpDbCalls;
  } cases[] = {
    { "no keys",                   NONE,  SHODAN_OK,           0, NONE,  ABUSEIPDB_OK,           0,  MISSING,    MISSING,    0, 0 },
    { "both answer",               OWN,   SHODAN_OK,           0, OWN,   ABUSEIPDB_OK,           0,  FILLED_REP, FILLED_IE,  1, 1 },
    { "not found, rejected",       OWN,   SHODAN_NOT_FOUND,    0, OWN,   ABUSEIPDB_KEY_REJECTED, 0,  REJECTED,   EMPTY_IE,   1, 1 },
    { "rejected, rate limited",    OWN,   SHODAN_KEY_REJECTED, 0, OWN,   ABUSEIPDB_RATE_LIMITED, 11, R"({"available":false,"reason":"vendor_unavailable","retry_after_seconds":11})", REJECTED, 1, 1 },
    { "rejected, missing",         OWN,   SHODAN_KEY_REJECTED, 0, NONE,  ABUSEIPDB_OK,           0,  MISSING,    REJECTED,   1, 0 },
    { "rate limited, down",        OWN,   SHODAN_RATE_LIMITED, 1, OWN,   ABUSEIPDB_UNAVAILABLE,  0,  UNAVAIL,    R"({"available":false,"reason":"vendor_unavailable","retry_after_seconds":1})", 1, 1 },
    { "down, answers",             OWN,   SHODAN_UNAVAILABLE,  0, OWN,   ABUSEIPDB_OK,           0,  FILLED_REP, UNAVAIL,    1, 1 },
    { "shodan sealed as other",    OTHER, SHODAN_OK,           0, OWN,   ABUSEIPDB_OK,           0,  FILLED_REP, DB_ERR,     0, 1 },
    { "abuseipdb sealed as other", NONE,  SHODAN_OK,           0, OTHER, ABUSEIPDB_OK,           0,  DB_ERR,     MISSING,    0, 0 },
  };
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    const char* name = cases[i].mp_name;
    static_resetVendorKeyStubs();
    static_setIpLookupVendorStubs();
    g_stub_IPLOOKUP_status = DB_OK;
    g_stub_SHODAN_lookup_status          = cases[i].m_shodan;
    g_stub_SHODAN_retry_after_seconds    = cases[i].m_shodanRetry;
    g_stub_ABUSEIPDB_status              = cases[i].m_abuseIpDb;
    g_stub_ABUSEIPDB_retry_after_seconds = cases[i].m_abuseIpDbRetry;
    if (cases[i].m_shodanKey != NONE)
      TEST_ASSERT_TRUE_MESSAGE(keyvault_trySeal(VENDORKEY_TEST_API_KEY_ID, cases[i].m_shodanKey == OWN ? "shodan" : "abuseipdb", VENDORKEY_SHODAN_KEY, strlen(VENDORKEY_SHODAN_KEY), g_stub_vendor_keys.ma_shodanSealedHex), name);
    if (cases[i].m_abuseIpDbKey != NONE)
      TEST_ASSERT_TRUE_MESSAGE(keyvault_trySeal(VENDORKEY_TEST_API_KEY_ID, cases[i].m_abuseIpDbKey == OWN ? "abuseipdb" : "shodan", VENDORKEY_ABUSEIPDB_KEY, strlen(VENDORKEY_ABUSEIPDB_KEY), g_stub_vendor_keys.ma_abuseIpDbSealedHex), name);

    char body[RESP_BUF];
    TEST_ASSERT_EQUAL_INT_MESSAGE(ENDPOINT_RUN_OK, static_ipLookupRun(REQUEST_TIER_PRO, body, sizeof(body)), name);
    TEST_ASSERT_NULL_MESSAGE(strstr(body, "#l="), body);
    char slots[2048];
    int written = snprintf(slots, sizeof(slots), R"("ptr":"one.one.one.one","reputation":%s,"internet_exposure":%s,"unavailable":{}})", cases[i].mp_reputation, cases[i].mp_internetExposure);
    TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(slots));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(body, slots), body);

    TEST_ASSERT_EQUAL_INT_MESSAGE(1, g_stub_vendor_keys_call_count, name);
    TEST_ASSERT_EQUAL_STRING_MESSAGE("b0b0b0", g_stub_vendor_keys_last_key_hash, name);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, g_stub_vendor_key_link_open_call_count, name);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, g_stub_vendor_key_apply_call_count, name);
    TEST_ASSERT_EQUAL_INT_MESSAGE(cases[i].m_shodanCalls, g_stub_SHODAN_lookup_count, name);
    TEST_ASSERT_EQUAL_INT_MESSAGE(cases[i].m_abuseIpDbCalls, g_stub_ABUSEIPDB_check_count, name);
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, g_stub_SHODAN_free_count, name);
    if (cases[i].m_shodanCalls > 0)
    {
      TEST_ASSERT_EQUAL_size_t_MESSAGE(strlen(VENDORKEY_SHODAN_KEY), g_stub_SHODAN_last_key_len, name);
      TEST_ASSERT_EQUAL_STRING_MESSAGE("8.8.8.8", g_stub_SHODAN_last_ip, name);
    }
    if (cases[i].m_abuseIpDbCalls > 0)
    {
      TEST_ASSERT_EQUAL_size_t_MESSAGE(strlen(VENDORKEY_ABUSEIPDB_KEY), g_stub_ABUSEIPDB_last_key_len, name);
      TEST_ASSERT_EQUAL_STRING_MESSAGE("8.8.8.8", g_stub_ABUSEIPDB_last_ip, name);
    }
  }
}

