void test_vendor_key_edit_calls_upstream_only_when_a_vendor_may_be_asked(void)
{
  const Endpoint_t* row = endpoint_findByMcpName("vendor_key_edit");
  TEST_ASSERT_NOT_NULL(row);
  TEST_ASSERT_NOT_NULL(row->m_callsUpstreamFunction);
  EndpointAnyParams_t params;
  memset(&params, 0, sizeof(params));
  static_vendorKeyParams(&params.m_vendorKeyEdit, "apply", "", VENDORKEY_SHODAN_KEY, "");
  TEST_ASSERT_TRUE(row->m_callsUpstreamFunction(&params));
  static_vendorKeyParams(&params.m_vendorKeyEdit, "apply", "", "", VENDORKEY_ABUSEIPDB_KEY);
  TEST_ASSERT_TRUE(row->m_callsUpstreamFunction(&params));
  static_vendorKeyParams(&params.m_vendorKeyEdit, "apply", "", "k", "");
  TEST_ASSERT_TRUE(row->m_callsUpstreamFunction(&params));
  static_vendorKeyParams(&params.m_vendorKeyEdit, "apply", "", "", "k");
  TEST_ASSERT_TRUE(row->m_callsUpstreamFunction(&params));
  static_vendorKeyParams(&params.m_vendorKeyEdit, "apply", "", "", "");
  params.m_vendorKeyEdit.m_isShodanDeleted    = true;
  params.m_vendorKeyEdit.m_isAbuseIpDbDeleted = true;
  TEST_ASSERT_FALSE(row->m_callsUpstreamFunction(&params));
  static_vendorKeyParams(&params.m_vendorKeyEdit, "status", "ab", "", "");
  TEST_ASSERT_TRUE(row->m_callsUpstreamFunction(&params));
  static_vendorKeyParams(&params.m_vendorKeyEdit, "status", "a", "", "");
  TEST_ASSERT_TRUE(row->m_callsUpstreamFunction(&params));
  static_vendorKeyParams(&params.m_vendorKeyEdit, "status", "", VENDORKEY_SHODAN_KEY, VENDORKEY_ABUSEIPDB_KEY);
  TEST_ASSERT_FALSE(row->m_callsUpstreamFunction(&params));
}

