void test_prose_names_the_manage_link_not_a_token(void)
{
  static const char* const phrases[] = { "edit token", "token of a manage", "token after #", "#t=" };
  static const char* const pages[] = { "/", "/pricing", "/quickstart", "/mcp-setup", "/ip-intelligence-api",
                                       "/terms", "/privacy", "/bot", "/vendor-keys", "/llms.txt",
                                       "/static/js/vendor_keys.js" };
  static const char* const docs[] = {
    DOCS_API_PATH,
    DOCS_MCP_PATH,
  };
  for (size_t i = 0; i < sizeof(pages) / sizeof(pages[0]) + sizeof(docs) / sizeof(docs[0]); i++)
  {
    bool is_page = i < sizeof(pages) / sizeof(pages[0]);
    const char* name = is_page ? pages[i] : docs[i - sizeof(pages) / sizeof(pages[0])];
    char* text = is_page ? static_pageText(name) : static_readDocsFile(name);
    for (char* c = text; *c != '\0'; c++)
      *c = (char)tolower((unsigned char)*c);
    for (size_t ph = 0; ph < sizeof(phrases) / sizeof(phrases[0]); ph++)
      TEST_ASSERT_NULL_MESSAGE(strstr(text, phrases[ph]), name);
    free(text);
  }
  for (int i = 0; i < endpoint_count; i++)
  {
    if (endpoints[i].mp_mcpToolName == NULL)
      continue;
    for (int j = -1; j < endpoints[i].m_paramCount; j++)
    {
      const char* source = j < 0 ? endpoints[i].mp_mcpToolDescription : endpoints[i].mp_params[j].mp_mcpArgDescription;
      if (source == NULL)
        continue;
      char lower[4096];
      snprintf(lower, sizeof(lower), "%s", source);
      for (char* c = lower; *c != '\0'; c++)
        *c = (char)tolower((unsigned char)*c);
      for (size_t ph = 0; ph < sizeof(phrases) / sizeof(phrases[0]); ph++)
        TEST_ASSERT_NULL_MESSAGE(strstr(lower, phrases[ph]), endpoints[i].mp_mcpToolName);
    }
  }
}

void test_docs_vendor_call_times_match_the_clients(void)
{
  TEST_ASSERT_EQUAL_INT(SHODAN_TIMEOUT_MS, ABUSEIPDB_TIMEOUT_MS);
  TEST_ASSERT_EQUAL_INT(0, SHODAN_TIMEOUT_MS % 1000);
  TEST_ASSERT_EQUAL_INT(0, DNS_PTR_DEADLINE_MS % 1000);
  const int call_seconds       = SHODAN_TIMEOUT_MS / 1000;
  const int total_seconds      = (SHODAN_TIMEOUT_MS + ABUSEIPDB_TIMEOUT_MS + DNS_PTR_DEADLINE_MS) / 1000;
  const int free_total_seconds = total_seconds + SHODAN_TIMEOUT_MS / 1000;
  char phrase[320];
  snprintf(phrase, sizeof(phrase), "each request takes at most %d seconds. With both keys and the PTR question, an answer can take about %d seconds. A free Shodan key needs a second Shodan request, so the answer can then take about %d seconds", call_seconds, total_seconds, free_total_seconds);
  static_assertPhraseCount(DOCS_API_PATH, phrase, 1);
  snprintf(phrase, sizeof(phrase), "Each vendor request takes\nat most %d seconds, so with both keys the call can take about %d seconds. A free Shodan key needs a\nsecond Shodan request, and the call can then take about %d seconds", call_seconds, total_seconds, free_total_seconds);
  static_assertPhraseCount(DOCS_MCP_PATH, phrase, 1);
}

