static X402PaymentStatus_t g_x402ParseStatus;
static int                 g_x402ParseCount;
static uint64_t            g_x402ParseLastAmount;
static X402SolanaStatus_t  g_x402CheckStatus;
static int                 g_x402CheckCount;

extern "C" X402PaymentStatus_t __wrap_x402_parsePaymentHeader(const char* value, size_t value_len, const X402Requirements_t* requirements, X402Payment_t* payment_out);
extern "C" X402PaymentStatus_t __wrap_x402_parsePaymentJson(const char* json, size_t json_len, const X402Requirements_t* requirements, X402Payment_t* payment_out);
extern "C" X402SolanaStatus_t  __wrap_x402_solana_checkTransaction(const uint8_t* tx, size_t tx_len, const X402SolanaPolicy_t* policy, X402SolanaCheck_t* check_out);

extern "C" X402PaymentStatus_t __wrap_x402_parsePaymentHeader(const char* value, size_t value_len, const X402Requirements_t* requirements, X402Payment_t* payment_out)
{
  (void)value;
  (void)value_len;
  g_x402ParseCount++;
  g_x402ParseLastAmount = requirements->m_amountAtomic;
  if (g_x402ParseStatus == X402_PAYMENT_OK)
  {
    memset(payment_out, 0, sizeof(*payment_out));
    payment_out->ma_transaction[0]      = 0x42;
    payment_out->m_transactionByteCount = 321;
  }
  return g_x402ParseStatus;
}

static char   g_parsedPaymentJson[1024];
static size_t g_parsedPaymentJsonLen;
extern "C" X402PaymentStatus_t __wrap_x402_parsePaymentJson(const char* json, size_t json_len, const X402Requirements_t* requirements, X402Payment_t* payment_out)
{
  g_parsedPaymentJsonLen = json_len < sizeof(g_parsedPaymentJson) - 1 ? json_len : sizeof(g_parsedPaymentJson) - 1;
  memcpy(g_parsedPaymentJson, json, g_parsedPaymentJsonLen);
  g_parsedPaymentJson[g_parsedPaymentJsonLen] = '\0';
  return __wrap_x402_parsePaymentHeader(json, json_len, requirements, payment_out);
}

extern "C" X402SolanaStatus_t __wrap_x402_solana_checkTransaction(const uint8_t* tx, size_t tx_len, const X402SolanaPolicy_t* policy, X402SolanaCheck_t* check_out)
{
  (void)tx;
  (void)tx_len;
  (void)policy;
  g_x402CheckCount++;
  if (g_x402CheckStatus == X402_SOLANA_OK)
  {
    memset(check_out->ma_messageHash, 0x11, sizeof(check_out->ma_messageHash));
    memset(check_out->ma_source, 0x22, sizeof(check_out->ma_source));
  }
  return g_x402CheckStatus;
}

