static bool static_x402FindLine(const char* buf, const char* name, char* line_out, size_t size)
{
  line_out[0] = '\0';
  const char* head_end = strstr(buf, "\r\n\r\n");
  TEST_ASSERT_NOT_NULL_MESSAGE(head_end, buf);
  char needle[64];
  snprintf(needle, sizeof(needle), "\r\n%s: ", name);
  const char* start = strstr(buf, needle);
  if (start == NULL || start >= head_end)
    return false;
  start += 2;
  const char* end = strstr(start, "\r\n");
  size_t len = (size_t)(end + 2 - start);
  TEST_ASSERT_TRUE(len < size);
  memcpy(line_out, start, len);
  line_out[len] = '\0';
  return true;
}

static void static_x402DecodeLine(const char* line, const char* name, char* out, size_t out_size)
{
  static const char ALPHABET[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  size_t name_len = strlen(name);
  size_t line_len = strlen(line);
  TEST_ASSERT_TRUE(line_len > name_len + 4);
  const char* text     = line + name_len + 2;
  size_t      text_len = line_len - name_len - 4;
  TEST_ASSERT_EQUAL_size_t(0, text_len % 4);
  size_t byte_count = 0;
  for (size_t i = 0; i < text_len; i += 4)
  {
    unsigned int group      = 0;
    int          data_count = 0;
    for (size_t k = 0; k < 4; k++)
    {
      group <<= 6;
      if (text[i + k] == '=')
        continue;
      const char* found = strchr(ALPHABET, text[i + k]);
      TEST_ASSERT_NOT_NULL(found);
      group |= (unsigned int)(found - ALPHABET);
      data_count++;
    }
    TEST_ASSERT_TRUE(byte_count + 3 < out_size);
    out[byte_count++] = (char)((group >> 16) & 0xFF);
    if (data_count > 2)
      out[byte_count++] = (char)((group >> 8) & 0xFF);
    if (data_count > 3)
      out[byte_count++] = (char)(group & 0xFF);
  }
  out[byte_count] = '\0';
}

static void static_assertOffer(const char* buf, const char* expected_json)
{
  char line[2048];
  TEST_ASSERT_TRUE_MESSAGE(static_x402FindLine(buf, "PAYMENT-REQUIRED", line, sizeof(line)), buf);
  char json[2048];
  static_x402DecodeLine(line, "PAYMENT-REQUIRED", json, sizeof(json));
  TEST_ASSERT_EQUAL_STRING(expected_json, json);
}

static void static_assertNoLine(const char* buf, const char* name)
{
  char line[2048];
  TEST_ASSERT_FALSE_MESSAGE(static_x402FindLine(buf, name, line, sizeof(line)), buf);
}

static void static_assertLine(const char* buf, const char* expected)
{
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, expected), buf);
}

