#define X402_TEST_MCP_PAYMENT R"("x402/payment":{"x402Version":2,"payload":{}})"

#define X402_TEST_MCP_PAID_META R"("_meta":{)" X402_TEST_MCP_PAYMENT R"(},)"

#define X402_TEST_MCP_SEP_KEYS \
  R"("io.modelcontextprotocol/protocolVersion":"2026-07-28","io.modelcontextprotocol/clientInfo":{"name":"p","version":"1"},"io.modelcontextprotocol/clientCapabilities":{})"

#define X402_TEST_MCP_MODERN_HEADERS(tool) "MCP-Protocol-Version: 2026-07-28\r\nMcp-Method: tools/call\r\nMcp-Name: " tool "\r\n"

#define X402_TEST_MCP_CVE_CALL(meta) \
  R"({"jsonrpc":"2.0","id":21,"method":"tools/call","params":{)" meta R"("name":"cve_lookup","arguments":{"cve_id":"CVE-2021-44228"}}})"

#define X402_TEST_MCP_OFFER_JSON(tool, amount, error) \
  "{\"x402Version\":2,\"error\":\"" error "\"," \
  "\"resource\":{\"url\":\"mcp://tool/" tool "\",\"description\":\"ContrastAPI request\",\"mimeType\":\"application/json\"}," \
  "\"accepts\":[{\"scheme\":\"exact\",\"network\":\"" X402_TEST_NETWORK "\",\"amount\":\"" amount "\"," \
  "\"asset\":\"" X402_TEST_MINT "\",\"payTo\":\"" X402_TEST_PAY_TO "\"," \
  "\"maxTimeoutSeconds\":60,\"extra\":{\"feePayer\":\"" X402_TEST_FEE_PAYER "\"}}]}"

#define X402_TEST_MCP_PAID_RESULT_START \
  R"("result":{"_meta":{"x402/payment-response":)" X402_TEST_RECEIPT_JSON R"(},"content":[{"type":"text","text":")"

static void static_callMcpX402(const char* headers, const char* body, char* buf, bool is_usage_line_read)
{
  static char req[96 * 1024];
  int written = snprintf(req, sizeof(req), "POST /mcp HTTP/1.1\r\nContent-Type: application/json\r\n%s\r\n%s", headers, body);
  TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(req));
  if (is_usage_line_read)
    static_callX402ForUsageLine(req, buf);
  else
    static_callX402(req, buf);
}

static void static_assertMcpOffer(const char* buf, const char* id, const char* offer_json, bool is_modern)
{
  static char expected[8192];
  int    head_len = snprintf(expected, sizeof(expected), R"({"jsonrpc":"2.0","id":%s,"result":{"content":[{"type":"text","text":")", id);
  TEST_ASSERT_TRUE(head_len > 0);
  size_t len = (size_t)head_len;
  for (const char* c = offer_json; *c != '\0'; c++)
  {
    TEST_ASSERT_TRUE(len + 2 < sizeof(expected));
    if (*c == '"' || *c == '\\')
      expected[len++] = '\\';
    expected[len++] = *c;
  }
  int tail_len = snprintf(expected + len, sizeof(expected) - len, R"("}],"structuredContent":%s,"isError":true%s}})", offer_json, is_modern ? R"(,"resultType":"complete")" : "");
  TEST_ASSERT_TRUE(tail_len > 0 && (size_t)tail_len < sizeof(expected) - len);
  TEST_ASSERT_EQUAL_STRING(expected, static_responseBody(buf));
}

static void static_assertMcpAnswer(const char* buf, const char* status_line, const char* body)
{
  TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), buf);
  static_assertLine(buf, status_line);
  TEST_ASSERT_EQUAL_STRING(body, static_responseBody(buf));
}

