void test_mcp_x402_open_refusals_are_answered(void)
{
  static_startX402();
  g_stub_CVELOOKUP_status               = DB_OK;
  g_stub_X402_FACILITATOR_verify_status = X402_FACILITATOR_VERIFY_INVALID;
  char buf[RESP_BUF];
  static_callMcpX402("", X402_TEST_MCP_CVE_CALL(X402_TEST_MCP_PAID_META), buf, false);
  TEST_ASSERT_EQUAL_INT(1, static_countResponses(buf));
  static_assertLine(buf, "HTTP/1.1 200 OK\r\n");
  static_assertMcpOffer(buf, "21", X402_TEST_MCP_OFFER_JSON("cve_lookup", "10000", "The payment was refused."), false);
  TEST_ASSERT_EQUAL_INT(1, g_stub_X402_LEDGER_release_count);

  static_resetX402Stubs();
  g_stub_X402_FACILITATOR_verify_status = X402_FACILITATOR_VERIFY_UNAVAILABLE;
  static_callMcpX402("", X402_TEST_MCP_CVE_CALL(X402_TEST_MCP_PAID_META), buf, false);
  static_assertMcpAnswer(buf, "HTTP/1.1 503 Service Unavailable\r\n",
                         R"({"jsonrpc":"2.0","id":21,"error":{"code":-32003,"message":"Payments are unavailable right now: retry shortly.","data":{"retry_after_seconds":5}}})");
  static_assertLine(buf, "\r\nRetry-After: 5\r\n");
  TEST_ASSERT_EQUAL_INT(1, g_stub_X402_LEDGER_release_count);

  static_resetX402Stubs();
  g_stub_X402_LEDGER_reservation.m_status = X402_LEDGER_PENDING;
  snprintf(g_stub_X402_LEDGER_reservation.ma_signature, sizeof(g_stub_X402_LEDGER_reservation.ma_signature), "%s", X402_TEST_PENDING_SIG);
  g_stub_X402_SOLANA_RPC_status = X402_SOLANA_RPC_SIGNATURE_FAILED;
  static_callMcpX402("", X402_TEST_MCP_CVE_CALL(X402_TEST_MCP_PAID_META), buf, false);
  TEST_ASSERT_EQUAL_INT(1, static_countResponses(buf));
  static_assertLine(buf, "HTTP/1.1 200 OK\r\n");
  static_assertMcpOffer(buf, "21", X402_TEST_MCP_OFFER_JSON("cve_lookup", "10000", "The payment was refused."), false);
  TEST_ASSERT_EQUAL_INT(1, g_stub_X402_LEDGER_release_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_CVELOOKUP_call_count);
}

