void test_docs_api_every_payment_line_gives_the_server_status(void)
{
  char* text = static_readDocsFile(DOCS_API_PATH);
  for (int i = 0; i < DOCS_PAYMENT_CODE_COUNT; i++)
  {
    const char* code = DOCS_PAYMENT_CODES[i];
    char buf[RESP_BUF];
    static_driveDocsPaymentAnswer(code, buf);
    int status = atoi(buf + strlen("HTTP/1.1 "));
    char code_ticks[48];
    snprintf(code_ticks, sizeof(code_ticks), "`%s`", code);
    int table_line_count = 0;
    for (const char* found = strstr(text, code_ticks); found; found = strstr(found + 1, code_ticks))
    {
      const char* line = found;
      while (line > text && line[-1] != '\n')
        line--;
      if (line[0] == '|' && line[1] == ' ' && line[2] >= '0' && line[2] <= '9')
      {
        TEST_ASSERT_EQUAL_INT_MESSAGE(status, atoi(line + 2), code);
        table_line_count++;
      }
      if (found - line >= 12 && strncmp(found - 6, " with ", 6) == 0 && found[-7] == '`')
        TEST_ASSERT_EQUAL_INT_MESSAGE(status, atoi(found - 10), code);
    }
    TEST_ASSERT_TRUE_MESSAGE(table_line_count >= 3, code);
  }
  char sentence[160];
  snprintf(sentence, sizeof(sentence), "longer than %d bytes; body code `payment_invalid`", (int)X402_PAYMENT_HEADER_MAX_LEN);
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(text, sentence), sentence);
  snprintf(sentence, sizeof(sentence), "The server settles at most %d fresh payments at once.", X402_REQUEST_MAX_SETTLE_COUNT);
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(text, sentence), sentence);
  free(text);
}

