void test_docs_api_source_lock_matches_the_sql_interval(void)
{
  char* sql = static_readDocsFile("sql/fn_x402.sql");
  const char* busy = strstr(sql, "AS is_source_busy");
  TEST_ASSERT_NOT_NULL(busy);
  const char* interval = NULL;
  for (const char* found = strstr(sql, "interval '"); found != NULL && found < busy; found = strstr(found + 1, "interval '"))
    interval = found;
  TEST_ASSERT_NOT_NULL(interval);
  int lock_seconds = atoi(interval + strlen("interval '"));
  TEST_ASSERT_TRUE(lock_seconds > 0);
  char unit[32];
  snprintf(unit, sizeof(unit), "%d seconds'", lock_seconds);
  TEST_ASSERT_EQUAL_INT(0, strncmp(interval + strlen("interval '"), unit, strlen(unit)));
  free(sql);

  char* text = static_readDocsFile(DOCS_API_PATH);
  char sentence[96];
  snprintf(sentence, sizeof(sentence), "its %d-second lock frees", lock_seconds);
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(text, sentence), sentence);
  snprintf(sentence, sizeof(sentence), "The lock lasts at most %d seconds.", lock_seconds);
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(text, sentence), sentence);
  free(text);
}

