static void static_assertBothSettlePlacesFree(void)
{
  X402RequestPayment_t first;
  X402RequestPayment_t second;
  const X402RequestPaymentSource_t source = { X402_REQUEST_PAYMENT_SOURCE_HEADER_BASE64, "aGVhZGVy", 8 };
  X402RequestOpenStatus_t first_status  = x402_request_dbOpenPayment(FAKE_CONN, &source, 1, X402_TEST_IP_SECRET, X402_TEST_MESSAGE_HASH, &first).m_status;
  X402RequestOpenStatus_t second_status = x402_request_dbOpenPayment(FAKE_CONN, &source, 1, X402_TEST_IP_SECRET, X402_TEST_MESSAGE_HASH, &second).m_status;
  if (first_status == X402_REQUEST_OPEN_OK)
    x402_request_dbReleaseUnserved(FAKE_CONN, &first, X402_REQUEST_UNSERVED_FAILED_RUN);
  if (second_status == X402_REQUEST_OPEN_OK)
    x402_request_dbReleaseUnserved(FAKE_CONN, &second, X402_REQUEST_UNSERVED_FAILED_RUN);
  TEST_ASSERT_EQUAL_INT_MESSAGE(X402_REQUEST_OPEN_OK, first_status, "first settle place");
  TEST_ASSERT_EQUAL_INT_MESSAGE(X402_REQUEST_OPEN_OK, second_status, "second settle place");
}

