typedef struct {
  char ma_head[64];
} HEALTHThreadAnswer_t;

static void* static_HEALTHGetOnItsOwnThread(void* arg)
{
  HEALTHThreadAnswer_t* answer = (HEALTHThreadAnswer_t*)arg;
  answer->ma_head[0] = '\0';
  int fds[2];
  if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) < 0)
    return NULL;
  ReceiveResult_t request;
  if (requestText_parse("GET /health HTTP/1.1\r\n\r\n", &request))
  {
    RequestHead_t head;
    request_readHead(&request, &head);
    request_handle(&request, &head, fds[1], TEST_IP, NULL, g_conn);
  }
  if (fcntl(fds[1], F_GETFD) != -1)
    close(fds[1]);
  size_t kept = 0;
  for (;;)
  {
    char chunk[4096];
    ssize_t read_len = read(fds[0], chunk, sizeof(chunk));
    if (read_len <= 0)
      break;
    size_t room = sizeof(answer->ma_head) - 1 - kept;
    size_t copy_len = (size_t)read_len < room ? (size_t)read_len : room;
    memcpy(answer->ma_head + kept, chunk, copy_len);
    kept += copy_len;
  }
  answer->ma_head[kept] = '\0';
  close(fds[0]);
  return NULL;
}

void test_HEALTH_kept_answer_is_per_thread(void)
{
  char buf[RESP_BUF];
  static_HEALTHGet(buf, sizeof(buf));
  TEST_ASSERT_NOT_NULL(strstr(buf, "HTTP/1.1 200 OK\r\n"));
  TEST_ASSERT_EQUAL_INT(1, g_stub_HEALTH_call_count);

  g_frozenClockMs = 1 - g_clockShiftMs;
  g_isClockFrozen = true;

  HEALTHThreadAnswer_t answer;
  pthread_t other;
  TEST_ASSERT_EQUAL_INT(0, pthread_create(&other, NULL, static_HEALTHGetOnItsOwnThread, &answer));
  TEST_ASSERT_EQUAL_INT(0, pthread_join(other, NULL));

  TEST_ASSERT_EQUAL_STRING_LEN("HTTP/1.1 200 OK\r\n", answer.ma_head, strlen("HTTP/1.1 200 OK\r\n"));
  TEST_ASSERT_EQUAL_INT(2, g_stub_HEALTH_call_count);
}

void test_docs_api_health_cache_age_matches_the_server(void)
{
  char sentence[96];
  int written = snprintf(sentence, sizeof(sentence), "keeps its last 200 answer for %d seconds", ENDPOINT_RUN_HEALTH_CACHE_TTL_MS / 1000);
  TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(sentence));
  char* api = static_readDocsFile(DOCS_API_PATH);
  TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countOccurrences(api, sentence), sentence);
  free(api);

  written = snprintf(sentence, sizeof(sentence), "up to %d seconds old", ENDPOINT_RUN_HEALTH_CACHE_TTL_MS / 1000);
  TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(sentence));
  char* mcp = static_readDocsFile(DOCS_MCP_PATH);
  TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countOccurrences(mcp, sentence), sentence);
  free(mcp);

}

